#!/data/data/com.termux/files/usr/bin/bash
# ============================================================================
# Rust on Termux with a fake rustup: extra targets, linker packs, root tweaks
# Generated by tpf from src/rustc-termux/ - do not edit, run ./tpf build.
# rustc-termux 2.0 (sources sha256:3c4dcb6f2bf1c9bf)
# ============================================================================
# shellcheck disable=SC2034  # available to the script, not always used
TPF_NAME=rustc-termux
TPF_VERSION=2.0
TPF_SOURCE_HASH=3c4dcb6f2bf1c9bf
# Rust on Termux (Android) with a "fake rustup".
#
#   rustc-termux.sh install      install Rust, the fake rustup/cargo/rustc, targets and linker packs
#   rustc-termux.sh reinstall    remove the fake rustup and install again from scratch
#   rustc-termux.sh uninstall    remove everything this tool wrote (asks before sharing/personal files)
#   rustc-termux.sh status       what is installed and its state
#   rustc-termux.sh doctor       check everything (--fix repairs, --full also compiles programs)
#   rustc-termux.sh test         compile and run a native program
#   rustc-termux.sh targets      list | add T | remove T
#   rustc-termux.sh packs        list | add NAME... | remove NAME...   (zig msvc ndk wasm)
#   rustc-termux.sh linker       list | add T --ndk|--clang TRIPLE|--zig ZT|-- CMD... | remove T | test T
#   rustc-termux.sh jobs N|off   limit parallel build jobs
#   rustc-termux.sh nightly on|off   simulated `cargo +nightly`
#   rustc-termux.sh log [NAME]   install logs
#
# Why a fake one?
#   The real rustup cannot run on Android, and the Rust package from Termux
#   ships the phone's own target only. The fake rustup sits on top of that
#   package and lets cargo rebuild the standard library for any other target
#   (WebAssembly, ...) from the official Rust sources.
#
# Everything that is written on the device:
#     ~/.rustup-fake/                  the fake tools and their state
#     ~/.bashrc  (~/.zshrc if used)    one PATH block between markers
#     $PREFIX/lib/rustlib/src          the Rust sources
#     ~/rust-termux.conf               saved choices (defaults for the next install)
#     ~/.cache/rust-termux-install/    logs
#   With root and only if you agree (each value is saved, then restored by
#   uninstall): Android settings (phantom process killer, Doze/background
#   exemption), kernel inotify limits, an optional swap file in /data/local,
#   the CPU governor until reboot, and a boot script in /data/adb/service.d
#   (or ~/.termux/boot). SELinux is never touched.
#
# `set -e` is deliberately NOT used: every step checks its own result so the
# script can explain what went wrong and carry on or stop cleanly.
set -uo pipefail

# --- tpf: begin src/lib/core.sh ---
# Basics shared by every installer: checks, clean exit, signals, wake lock.
#
# Commands: have is_uint is_port require_termux require_aarch64
#           on_exit wake_lock
# --- tpf: begin src/lib/ui.sh ---
# Output style shared by every installer (see docs/STYLE.md).
#
#   [INFO] [ OK ] [ ?? ] [WARN]    six columns: the text always starts at column 8
#   [ERROR]                        danger: seven columns, written to stderr
#   [.   ] [..  ] [... ] ...       a task that is running (see task)
#
# Commands: info ok warn err detail step banner die
#           ask_yes_no ask_input ask_choice task
# Variable: TPF_ASSUME=yes|no answers every question without asking.

_UI_FRAMES=('[.   ]' '[..  ]' '[... ]' '[ ...]' '[  ..]' '[   .]')
_UI_CURSOR_HIDDEN=0
_TASK_PID=""

# ui_colors on|off|auto
ui_colors() {
    local mode="${1:-auto}"
    if [ "$mode" = auto ]; then
        if [ -t 1 ] && [ -z "${NO_COLOR:-}" ] && [ "${TERM:-}" != dumb ]; then mode=on; else mode=off; fi
    fi
    if [ "$mode" = on ]; then
        C_RESET=$'\033[0m'; C_BOLD=$'\033[1m'; C_DIM=$'\033[2m'
        C_INFO=$'\033[1;34m'; C_OK=$'\033[1;32m'; C_WARN=$'\033[1;33m'
        C_ERR=$'\033[1;31m'; C_ASK=$'\033[1;36m'
    else
        C_RESET=""; C_BOLD=""; C_DIM=""
        C_INFO=""; C_OK=""; C_WARN=""; C_ERR=""; C_ASK=""
    fi
}
ui_colors auto

# True when a running task can be animated in place.
_ui_animated() {
    [ -t 1 ] && [ "${TERM:-}" != dumb ] && [ -z "${TPF_NO_ANIM:-}" ]
}

# Everything printed is also appended, without colours, to $TPF_LOG_DIR/run.log.
_ui_log() {
    [ -n "${TPF_LOG_DIR:-}" ] && [ -d "${TPF_LOG_DIR}" ] || return 0
    printf '%s %-5s %s\n' "$(date '+%Y-%m-%d %H:%M:%S')" "$1" "$2" >>"$TPF_LOG_DIR/run.log" 2>/dev/null || true
}

_ui_line() {   # colour tag text
    printf '%s%s%s %s\n' "$1" "$2" "$C_RESET" "$3"
}

info() { _ui_line "$C_INFO" '[INFO]' "$*"; _ui_log INFO "$*"; }
ok()   { _ui_line "$C_OK" '[ OK ]' "$*"; _ui_log OK "$*"; }
warn() { _ui_line "$C_WARN" '[WARN]' "$*"; _ui_log WARN "$*"; }
err()  { _ui_line "$C_ERR" '[ERROR]' "$*" >&2; _ui_log ERROR "$*"; }

# A dimmed line aligned with the text of the lines above.
detail() { printf '       %s%s%s\n' "$C_DIM" "$*" "$C_RESET"; }

step() {
    printf '\n%s=== %s ===%s\n' "$C_INFO" "$*" "$C_RESET"
    _ui_log STEP "$*"
}

# banner TITLE [SUBTITLE]
banner() {
    local bar="============================================================"
    printf '\n%s%s\n %s\n' "$C_OK" "$bar" "$1"
    [ -z "${2:-}" ] || printf ' %s\n' "$2"
    printf '%s%s\n' "$bar" "$C_RESET"
}

die() {
    err "$*"
    if [ -n "${TPF_LOG_DIR:-}" ] && [ -d "${TPF_LOG_DIR}" ]; then
        printf '       %sLogs: %s%s\n' "$C_DIM" "$TPF_LOG_DIR" "$C_RESET" >&2
    fi
    exit 1
}

# ---------------------------------------------------------------------------
# Questions. They read /dev/tty, so they also work with `curl ... | bash`.
# The answer of ask_input / ask_choice is left in $ANSWER.
# ---------------------------------------------------------------------------
_ui_have_tty() { ( : </dev/tty ) 2>/dev/null; }

_ui_prompt() {   # text; reads one line from the terminal into $_UI_REPLY
    _UI_REPLY=""
    printf '%s[ ?? ]%s %s' "$C_ASK" "$C_RESET" "$1" >/dev/tty
    IFS= read -r _UI_REPLY </dev/tty || _UI_REPLY=""
}

# ask_yes_no "question" [yes|no]   -> status 0 for yes
ask_yes_no() {
    local question="$1" def="${2:-no}" hint
    case "${TPF_ASSUME:-}" in
        yes) _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: yes]${C_RESET}"; return 0 ;;
        no)  _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: no]${C_RESET}"; return 1 ;;
    esac
    if [ "$def" = yes ]; then hint="[Y/n]"; else hint="[y/N]"; fi
    if _ui_have_tty; then
        _ui_prompt "$question $hint "
        case "$_UI_REPLY" in
            y|Y|yes|Yes|YES|o|O|oui|Oui|OUI) return 0 ;;
            n|N|no|No|NO|non|Non|NON) return 1 ;;
            *) [ "$def" = yes ]; return ;;
        esac
    fi
    warn "No terminal available: default answer \"$def\" used ($question)"
    [ "$def" = yes ]
}

# ask_input "question" "default"   -> $ANSWER
ask_input() {
    local question="$1" def="${2:-}"
    ANSWER="$def"
    if [ -n "${TPF_ASSUME:-}" ]; then
        _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: ${def:-empty}]${C_RESET}"
        return 0
    fi
    if _ui_have_tty; then
        _ui_prompt "$question${def:+ [$def]} "
        [ -z "$_UI_REPLY" ] || ANSWER="$_UI_REPLY"
        return 0
    fi
    warn "No terminal available: default \"${def:-empty}\" used ($question)"
}

# ask_choice "question" DEFAULT option...   -> $ANSWER (one of the options)
ask_choice() {
    local question="$1" def="$2" opt n=0
    shift 2
    ANSWER="$def"
    if [ -n "${TPF_ASSUME:-}" ] || ! _ui_have_tty; then
        _ui_line "$C_ASK" '[ ?? ]' "$question ${C_DIM}[auto: $def]${C_RESET}"
        return 0
    fi
    _ui_line "$C_ASK" '[ ?? ]' "$question"
    for opt in "$@"; do
        n=$((n + 1))
        printf '       %s%d)%s %s%s\n' "$C_BOLD" "$n" "$C_RESET" "$opt" "$([ "$opt" = "$def" ] && printf ' (default)')"
    done
    _ui_prompt "Choice [1-$n or name] "
    n=0
    for opt in "$@"; do
        n=$((n + 1))
        if [ "$_UI_REPLY" = "$n" ] || [ "$_UI_REPLY" = "$opt" ]; then ANSWER="$opt"; return 0; fi
    done
    [ -z "$_UI_REPLY" ] || warn "\"$_UI_REPLY\" is not an option: default \"$def\" used"
}

# ---------------------------------------------------------------------------
# task "message" command [args...]
#
# Runs the command with its output sent to a log file and shows an animated
# [.   ] [..  ] [... ] marker while it runs, then replaces it by [ OK ] or
# [ERROR]. Returns the status of the command; on failure the last lines of the
# log are shown. The command runs in a subshell: variables it sets are lost.
# ---------------------------------------------------------------------------
# A process and all its descendants (apt starts dpkg, cargo starts rustc, ...).
_ui_tree() {
    local child
    echo "$1"
    for child in $(pgrep -P "$1" 2>/dev/null); do _ui_tree "$child"; done
}

_ui_kill_tree() {
    local pids
    pids="$(_ui_tree "$1")"
    # shellcheck disable=SC2086
    kill $pids 2>/dev/null || true
}

_ui_cleanup() {
    if [ "$_UI_CURSOR_HIDDEN" = 1 ]; then printf '\033[?25h'; _UI_CURSOR_HIDDEN=0; fi
}

_task_logfile() {
    local slug
    slug="$(printf '%s' "$1" | tr -c 'A-Za-z0-9' '-' | tr -s '-' | sed 's/^-//; s/-$//' | cut -c1-48)"
    printf '%s/%s.log' "${TPF_LOG_DIR:-${TMPDIR:-/tmp}}" "${slug:-task}"
}

# spin_run LABEL LOGFILE command [args...]
# The running marker alone: the command's output goes to LOGFILE, the marker
# is erased when it ends, nothing else is printed. Returns the command's status.
spin_run() {
    local label="$1" log="$2" rc=0 i=0
    shift 2
    mkdir -p "$(dirname "$log")" 2>/dev/null || true
    if _ui_animated; then
        "$@" >"$log" 2>&1 </dev/null &
        _TASK_PID=$!
        printf '\033[?25l'; _UI_CURSOR_HIDDEN=1
        while kill -0 "$_TASK_PID" 2>/dev/null; do
            printf '\r\033[K%s%s%s %s' "$C_INFO" "${_UI_FRAMES[i % ${#_UI_FRAMES[@]}]}" "$C_RESET" "$label"
            i=$((i + 1))
            sleep 0.15
        done
        wait "$_TASK_PID"; rc=$?
        _TASK_PID=""
        printf '\r\033[K'
        _ui_cleanup
    else
        _ui_line "$C_INFO" '[ .. ]' "$label"
        "$@" >"$log" 2>&1 </dev/null; rc=$?
    fi
    return "$rc"
}

task() {
    local msg="$1" log rc=0 started=$SECONDS took=""
    shift
    [ -z "${TPF_LOG_DIR:-}" ] || mkdir -p "$TPF_LOG_DIR" 2>/dev/null || true
    log="$(_task_logfile "$msg")"
    spin_run "$msg" "$log" "$@" || rc=$?
    [ $((SECONDS - started)) -lt 2 ] || took=" ${C_DIM}($((SECONDS - started))s)${C_RESET}"
    if [ "$rc" -eq 0 ]; then
        _ui_line "$C_OK" '[ OK ]' "$msg$took"
        _ui_log OK "$msg"
    else
        _ui_line "$C_ERR" '[ERROR]' "$msg (exit $rc)$took" >&2
        _ui_log ERROR "$msg (exit $rc)"
        if [ -s "$log" ]; then
            tail -n 8 "$log" | sed "s/^/       ${C_DIM}/; s/\$/${C_RESET}/" >&2
            printf '       %sFull log: %s%s\n' "$C_DIM" "$log" "$C_RESET" >&2
        fi
    fi
    return "$rc"
}
# --- tpf: end src/lib/ui.sh ---

have()    { command -v "$1" >/dev/null 2>&1; }
is_uint() { case "${1:-}" in '' | *[!0-9]*) return 1 ;; esac; }
is_port() { is_uint "${1:-}" && [ "$1" -ge 1 ] && [ "$1" -le 65535 ]; }

require_termux() {
    case "${PREFIX:-}" in
        *com.termux*) ;;
        *) die "This script must be run inside Termux." ;;
    esac
    [ -n "${HOME:-}" ] || die "\$HOME is not set."
}

require_aarch64() {
    case "$(uname -m)" in
        aarch64 | arm64) ;;
        *) die "Only 64-bit ARM (aarch64) is supported (this device: $(uname -m))." ;;
    esac
}

# ---------------------------------------------------------------------------
# Clean exit. Register cleanup commands with on_exit; they run in reverse
# order when the script ends, whatever the reason (end, die, Ctrl-C).
# ---------------------------------------------------------------------------
_TPF_EXIT_CMDS=()

on_exit() { _TPF_EXIT_CMDS+=("$1"); }

_tpf_exit() {
    local status=$? i
    trap - EXIT
    if [ -n "${_TASK_PID:-}" ]; then _ui_kill_tree "$_TASK_PID"; fi
    _ui_cleanup
    for ((i = ${#_TPF_EXIT_CMDS[@]} - 1; i >= 0; i--)); do
        eval "${_TPF_EXIT_CMDS[i]}" || true
    done
    exit "$status"
}

_tpf_signal() {   # name status
    printf '\n' >&2
    err "Interrupted ($1)."
    exit "$2"
}

trap _tpf_exit EXIT
trap '_tpf_signal INT 130' INT
trap '_tpf_signal TERM 143' TERM

# wake_lock: keep Android from suspending Termux until the script ends.
_TPF_WAKE=0
wake_lock() {
    [ "$_TPF_WAKE" = 0 ] || return 0
    if have termux-wake-lock && termux-wake-lock >/dev/null 2>&1; then
        _TPF_WAKE=1
        on_exit 'termux-wake-unlock >/dev/null 2>&1'
    fi
    return 0
}
# --- tpf: end src/lib/core.sh ---
# --- tpf: begin src/lib/cmd.sh ---
# Command dispatcher shared by every tool, so that all of them speak the same way:
#
#   tool.sh [options] install | reinstall | uninstall | status | start | stop | restart | log | help
#
# A tool defines one function cmd_<name> per command (dashes become underscores),
# registers them, and calls tpf_main:
#
#   cmd_install()   { ...; }
#   cmd_uninstall() { ...; }
#   add_command install   "Install the tool"
#   add_command uninstall "Remove the tool"
#   add_alias   setup install        # optional: another word for a command
#   tpf_main "$@"
#
# Optional hooks and variables:
#   tool_opt "$@"            handle a tool option: return 0 and set TOOL_SHIFT (default 1)
#   tool_usage               extra help text, printed after the list of commands
#   TOOL_OPTIONS_HELP        text for the tool's own options, printed with the common ones
#   TOOL_DEFAULT_COMMAND     command used when none is given (default: help)
#   TOOL_LOG_DIR             log directory (default: ~/.cache/tpf/<name>)
#   TOOL_RAW_COMMANDS        commands whose words and options after the command name are
#                            passed to them untouched (they have their own options)
#
# "reinstall" exists as soon as install and uninstall do: uninstall (TPF_KEEP_DATA=1
# tells it to keep the user's data), then install. A tool may define its own.
# "help" and "version" always exist. The command words after the first one are
# passed to the command as arguments.
# --- tpf: begin src/lib/args.sh ---
# Command line options common to every installer.
#
#   -y, --yes   -n, --no   --no-color   --log-dir DIR   -V, --version   -h, --help
#
# In the option loop of a script:
#
#   while [ $# -gt 0 ]; do
#       case "$1" in
#           --my-option) MY=1 ;;
#           *) std_opt "$@" || die "Unknown option: $1 (try --help)"; shift "$STD_SHIFT"; continue ;;
#       esac
#       shift
#   done
#
# The script defines usage() and may print std_usage inside it.

STD_SHIFT=1
TPF_ASSUME="${TPF_ASSUME:-}"

# need_value OPTION ARGC   -> dies when an option that takes a value has none
need_value() {
    [ "$2" -ge 2 ] || die "Option $1 needs a value (try --help)"
}

std_usage() {
    cat <<'USAGE'
  -y, --yes        Answer "yes" to every question
  -n, --no         Answer "no" to every question
      --no-color   Plain output without colours
      --log-dir D  Write the logs to D
  -V, --version    Print the version and exit
  -h, --help       Show this help
USAGE
}

# std_opt "$@": handles the first argument if it is a common option.
# Returns 1 when it is not one. Sets STD_SHIFT to the number of arguments used.
std_opt() {
    STD_SHIFT=1
    case "$1" in
        -y | --yes) TPF_ASSUME=yes ;;
        -n | --no) TPF_ASSUME=no ;;
        --no-color) ui_colors off ;;
        --log-dir)
            need_value "$1" $#
            TPF_LOG_DIR="$2"
            STD_SHIFT=2
            ;;
        --log-dir=*) TPF_LOG_DIR="${1#*=}" ;;
        -V | --version)
            printf '%s %s\n' "$TPF_NAME" "$TPF_VERSION"
            exit 0
            ;;
        -h | --help)
            if declare -F usage >/dev/null; then usage; else printf 'Usage: %s [options]\n' "$TPF_NAME"; fi
            exit 0
            ;;
        *) return 1 ;;
    esac
}
# --- tpf: end src/lib/args.sh ---
# --- tpf: begin src/lib/log.sh ---
# Log directory of a script. Everything printed by info/ok/warn/err/step is also
# recorded (without colours) in $TPF_LOG_DIR/run.log; task output goes to one file
# per task in the same directory.
#
# Command: log_init [DIR]   (default: ~/.cache/tpf/$TPF_NAME, or --log-dir)

log_init() {
    TPF_LOG_DIR="${TPF_LOG_DIR:-${1:-$HOME/.cache/tpf/$TPF_NAME}}"
    mkdir -p "$TPF_LOG_DIR" 2>/dev/null || { warn "Cannot create the log directory $TPF_LOG_DIR"; TPF_LOG_DIR=""; return 0; }
    export TPF_LOG_DIR
}
# --- tpf: end src/lib/log.sh ---

_TPF_CMDS=()
_TPF_CMD_HELP=()
_TPF_ALIASES=()      # "alias=command"
TOOL_SHIFT=1
TPF_KEEP_DATA=0
CMD_ARGS=()

# add_command NAME "one line description"
add_command() {
    _TPF_CMDS+=("$1")
    _TPF_CMD_HELP+=("$2")
}

# add_alias ALIAS COMMAND
add_alias() { _TPF_ALIASES+=("$1=$2"); }

# _cmd_resolve WORD: prints the command a word stands for (itself if not an alias)
_cmd_resolve() {
    local pair
    for pair in "${_TPF_ALIASES[@]}"; do
        if [ "${pair%%=*}" = "$1" ]; then printf '%s' "${pair#*=}"; return 0; fi
    done
    printf '%s' "$1"
}

_cmd_aliases_of() {   # command -> "a, b" (empty if none)
    local pair out=""
    for pair in "${_TPF_ALIASES[@]}"; do
        if [ "${pair#*=}" = "$1" ]; then out="${out:+$out, }${pair%%=*}"; fi
    done
    printf '%s' "$out"
}

_cmd_is_raw() {
    local name
    for name in ${TOOL_RAW_COMMANDS:-}; do [ "$name" = "$(_cmd_resolve "$1")" ] && return 0; done
    return 1
}

_cmd_known() {
    local name
    for name in "${_TPF_CMDS[@]}"; do [ "$name" = "$1" ] && return 0; done
    return 1
}

cmd_help() {
    local i extra
    printf 'Usage: %s [options] <command> [arguments]\n\nCommands:\n' "${TPF_SCRIPT:-$TPF_NAME}"
    for i in "${!_TPF_CMDS[@]}"; do
        extra="$(_cmd_aliases_of "${_TPF_CMDS[i]}")"
        printf '  %-12s %s%s\n' "${_TPF_CMDS[i]}" "${_TPF_CMD_HELP[i]}" "${extra:+ (also: $extra)}"
    done
    printf '  %-12s %s\n' help "Show this help"
    printf '  %-12s %s\n' version "Print the version"
    if declare -F tool_usage >/dev/null; then
        printf '\n'
        tool_usage
    fi
    printf '\nOptions:\n'
    if [ -n "${TOOL_OPTIONS_HELP:-}" ]; then printf '%s\n' "$TOOL_OPTIONS_HELP"; fi
    std_usage
}

cmd_version() { printf '%s %s\n' "$TPF_NAME" "$TPF_VERSION"; }

cmd_reinstall() {
    TPF_KEEP_DATA=1
    cmd_uninstall "$@" || die "The removal step failed: nothing was installed again."
    TPF_KEEP_DATA=0
    cmd_install "$@"
}

# std_opt calls usage() for -h/--help.
usage() { cmd_help; }

tpf_main() {
    local command_word="" fn status=0 only_args=0
    TPF_SCRIPT="${0##*/}"
    CMD_ARGS=()
    while [ $# -gt 0 ]; do
        if [ -n "$command_word" ] && _cmd_is_raw "$command_word"; then
            CMD_ARGS+=("$@")
            break
        fi
        if [ "$only_args" = 1 ] || [ "${1#-}" = "$1" ]; then
            if [ -z "$command_word" ]; then command_word="$1"; else CMD_ARGS+=("$1"); fi
            shift
            continue
        fi
        if [ "$1" = "--" ]; then only_args=1; shift; continue; fi
        TOOL_SHIFT=1
        if declare -F tool_opt >/dev/null && tool_opt "$@"; then
            shift "$TOOL_SHIFT"
        elif std_opt "$@"; then
            shift "$STD_SHIFT"
        else
            err "Unknown option: $1 (try: $TPF_SCRIPT help)"
            exit 2
        fi
    done

    if declare -F cmd_install >/dev/null && declare -F cmd_uninstall >/dev/null && ! _cmd_known reinstall; then
        add_command reinstall "Remove (keeping your data), then install again"
    fi
    command_word="${command_word:-${TOOL_DEFAULT_COMMAND:-help}}"
    command_word="$(_cmd_resolve "$command_word")"
    case "$command_word" in
        help | version) ;;
        *)
            if ! _cmd_known "$command_word"; then
                err "Unknown command: $command_word (try: $TPF_SCRIPT help)"
                exit 2
            fi
            ;;
    esac
    fn="cmd_${command_word//-/_}"
    if ! declare -F "$fn" >/dev/null; then
        err "The command $command_word is registered but $fn is not defined."
        exit 2
    fi
    case "$command_word" in help | version) ;; *) log_init "${TOOL_LOG_DIR:-}" ;; esac
    "$fn" "${CMD_ARGS[@]}" || status=$?
    exit "$status"
}
# --- tpf: end src/lib/cmd.sh ---
# --- tpf: begin src/lib/pkg.sh ---
# Termux package helpers (apt).
#
# Commands: pkg_update  pkg_install PKG...  apt_install LOGNAME PKG...
#           apt_repair  dpkg_installed PKG
# Variable: APT_OPTS (non-interactive options for apt-get)

export DEBIAN_FRONTEND=noninteractive
APT_OPTS=(-y -o Dpkg::Options::=--force-confdef -o Dpkg::Options::=--force-confold)

# Finish interrupted installs and fix broken dependencies.
apt_repair() {
    dpkg --configure -a >/dev/null 2>&1 || true
    apt-get "${APT_OPTS[@]}" -f install >/dev/null 2>&1 || true
}

# Install packages; if that fails, repair apt once and try again.
_apt_install_run() {
    apt-get "${APT_OPTS[@]}" install "$@" && return 0
    apt_repair
    apt-get "${APT_OPTS[@]}" install "$@"
}

# apt_install LOGNAME PKG...   quiet: the output goes to $TPF_LOG_DIR/LOGNAME.log
apt_install() {
    local name="$1"
    shift
    _apt_install_run "$@" >"${TPF_LOG_DIR:-${TMPDIR:-/tmp}}/$name.log" 2>&1
}

# pkg_install PKG...   shows a running marker, then [ OK ] or [ERROR]
pkg_install() { task "Installing $*" _apt_install_run "$@"; }

pkg_update() { task "Updating the package lists" apt-get "${APT_OPTS[@]}" update; }

dpkg_installed() {
    [ "$(dpkg-query -W -f='${Status}' "$1" 2>/dev/null)" = "install ok installed" ]
}
# --- tpf: end src/lib/pkg.sh ---
# --- tpf: begin src/rustc-termux/compat.sh ---
# The output interface this tool was written with, on top of the shared ui
# module: the code keeps calling denied, plain, title, phase_begin, run_logged...
# The percentage bar is replaced by the animated markers of the shared module.

PHASE_BASE=0
PHASE_W=0
TEST_DIR=""
FAILED=0

denied() { err "$*"; }
plain() { printf '%s\n' "$*"; }
title() { step "$1"; }

bar_start() { :; }
bar_set() { :; }
bar_hide() { :; }
bar_render() { :; }
bar_finish() { :; }

# phase_begin "Title" WEIGHT: a titled step.
phase_begin() {
    PHASE_BASE=$((PHASE_BASE + PHASE_W))
    PHASE_W="$2"
    step "$1"
}
pct_at() { echo $((PHASE_BASE + PHASE_W * $1 / $2)); }

# run_logged HI EXPECTED_SECONDS LOGFILE command...
# Runs the command with its output sent to LOGFILE, showing a running marker
# named after the log file (apt_update.log -> "Apt update").
run_logged() {
    local log="$3" label
    shift 3
    label="$(basename "$log" .log | tr '_-' '  ')"
    spin_run "${label^}" "$log" "$@"
}

rust_cleanup() {
    if [ -n "$TEST_DIR" ] && [ -d "$TEST_DIR" ]; then rm -rf "$TEST_DIR"; fi
}
on_exit rust_cleanup
