# --- tpf: begin src/rustc-termux/common.sh ---
# Paths, saved choices, root helpers and removal functions shared by the commands.

# ---------------------------------------------------------------------------
# Everything this tool writes on the device is listed here. Nothing else
# is ever touched, which is what lets the uninstaller be exhaustive.
# ---------------------------------------------------------------------------
BASE="${HOME:-}/.rustup-fake"               # fake rustup / cargo / rustc
LEGACY_PROOT_BASE="${HOME:-}/.rustup-proot" # left by an older proot-based script
CONF="${HOME:-}/rust-termux.conf"           # saved choices (defaults for the next run)
LOG_DIR="${HOME:-}/.cache/rust-termux-install"
TOOL_LOG_DIR="$LOG_DIR"
TARGETS_FILE="$BASE/targets"
SELF="$(readlink -f "${BASH_SOURCE[0]}" 2>/dev/null || printf '%s' "${BASH_SOURCE[0]}")"
CARGO_DATA_DIR="${HOME:-}/.cargo"                 # crate cache, tools from `cargo install`
RC_FILES=("${HOME:-}/.bashrc" "${HOME:-}/.zshrc") # PATH is added here, between markers
RC_BEGIN="# >>> rust-termux >>>"
RC_END="# <<< rust-termux <<<"
REAL_RUSTC="${RUSTUP_FAKE_REAL_RUSTC:-${PREFIX:-}/bin/rustc}" # the compiler from the Termux package
REAL_CARGO="${RUSTUP_FAKE_REAL_CARGO:-${PREFIX:-}/bin/cargo}"

DEPS_REQUIRED=(rust clang make binutils pkg-config lld curl tar xz-utils)
DEPS_OPTIONAL=(cmake git openssl)
# Tiny base tools that other things rely on: never removed by the uninstaller.
PROTECTED_PKGS=" curl tar xz-utils coreutils "

PURGE_DATA=0

q() { printf '%q' "$1"; }

# ---------------------------------------------------------------------------
# Saved choices (~/rust-termux.conf), reused as defaults by the next run
# ---------------------------------------------------------------------------
PREV_CONF=0
load_prev_conf() {
    PREV_CONF=0
    [ -f "$CONF" ] || return 0
    if bash -n "$CONF" 2>/dev/null; then
        PREV_CONF=1
        info "Previous settings found: $CONF"
    else
        warn "$CONF contains a syntax error: saved as $CONF.bak, defaults used."
        mv -f "$CONF" "$CONF.bak" 2>/dev/null
    fi
}
# Read in a subshell so the file cannot overwrite this script's own variables.
conf_get() {
    [ "$PREV_CONF" = 1 ] || return 0
    (
        set +u
        . "$CONF" >/dev/null 2>&1 </dev/null
        printf '%s' "${!1:-}"
    )
}
conf_has() { [ "$PREV_CONF" = 1 ] && grep -q "^$1=" "$CONF" 2>/dev/null; }
prev_or() {
    local v
    v="$(conf_get "$1")"
    if [ -n "$v" ]; then printf '%s' "$v"; else printf '%s' "$2"; fi
}
prev_flag() { if conf_has "$1"; then if [ "$(conf_get "$1")" = 1 ]; then echo yes; else echo no; fi; else echo "$2"; fi; }

# ---------------------------------------------------------------------------
# Environment
# ---------------------------------------------------------------------------
check_termux() {
    [ -n "${PREFIX:-}" ] && [[ "$PREFIX" == *"com.termux"* ]] ||
        die "This script must be run INSIDE Termux (\$PREFIX missing or unexpected)."
    [ -n "${HOME:-}" ] || die "\$HOME is not set."
}

# Shims left in the PATH of the current shell by a previous install must not
# be picked up by this script: it always talks to the real tools.
strip_shims_from_path() {
    PATH="$(printf '%s' "$PATH" | tr ':' '\n' | grep -vxF -e "$BASE/bin" -e "$LEGACY_PROOT_BASE/bin" | paste -sd: -)"
    export PATH
    hash -r 2>/dev/null || true
}

# ---------------------------------------------------------------------------
# Android facts and ROOT. Shared by the installer and the uninstaller: what the
# installer changes with root is reverted by the very same functions.
#
# Rules followed everywhere below:
#   - nothing is changed without a question (or an explicit option);
#   - the value found BEFORE each change is saved in ~/rust-termux.conf and
#     put back by the uninstaller (or by the next install);
#   - SELinux, the system partition and the boot image are never touched;
#   - every change is read back, and reported as an error if it did not stick.
# ---------------------------------------------------------------------------
ROOT_ALL="phantom doze inotify oom swap perf"
ROOT_RISKY=" swap perf " # never enabled by --yes alone
SU_BIN=""
ROOT_OK=0
ANDROID_SDK=0
ANDROID_REL=""
TREBLE=""
TERMUX_PKG=""
BOOT_SCRIPT_NAME="rust-termux.sh"

android_info() {
    ANDROID_SDK=0
    ANDROID_REL=""
    TREBLE=""
    if have getprop; then
        ANDROID_SDK="$(getprop ro.build.version.sdk 2>/dev/null)"
        ANDROID_REL="$(getprop ro.build.version.release 2>/dev/null)"
        TREBLE="$(getprop ro.treble.enabled 2>/dev/null)"
    fi
    is_uint "${ANDROID_SDK:-}" || ANDROID_SDK=0
    TERMUX_PKG="${PREFIX#/data/data/}"
    TERMUX_PKG="${TERMUX_PKG%%/*}"
    [ -n "$TERMUX_PKG" ] || TERMUX_PKG="com.termux"
}

# Where is su? (Magisk, KernelSU, APatch, older layouts)
find_su() {
    local c p
    SU_BIN=""
    for c in su /system/bin/su /system/xbin/su /sbin/su /debug_ramdisk/su \
        /data/adb/magisk/su /data/adb/ksu/bin/su /data/adb/ap/bin/su; do
        case "$c" in
            /*) [ -x "$c" ] && {
                SU_BIN="$c"
                return 0
            } ;;
            *)
                p="$(command -v "$c" 2>/dev/null)"
                [ -n "$p" ] && {
                    SU_BIN="$p"
                    return 0
                }
                ;;
        esac
    done
    return 1
}

# Runs one command line as root. Termux's LD_LIBRARY_PATH / LD_PRELOAD must not
# leak into the root shell, otherwise Android's own tools (settings, dumpsys...)
# crash on Termux's libraries.
rsu() {
    local cmd="$1" pre
    pre='unset LD_LIBRARY_PATH LD_PRELOAD; export PATH=/system/bin:/system/xbin:/vendor/bin:/sbin:/data/adb/magisk:/data/adb/ksu/bin:$PATH; '
    if [ "$(id -u)" = 0 ]; then
        timeout "${ROOT_TIMEOUT:-30}" sh -c "$pre$cmd"
    else
        [ -n "$SU_BIN" ] || return 127
        timeout "${ROOT_TIMEOUT:-30}" "$SU_BIN" -c "$pre$cmd" </dev/null
    fi
}

# 0 = root works (the root manager may ask the user to confirm, hence the long wait)
detect_root() {
    local out
    ROOT_OK=0
    if [ "$(id -u)" = 0 ]; then
        ROOT_OK=1
        return 0
    fi
    find_su || return 1
    out="$(ROOT_TIMEOUT=60 rsu 'id -u' 2>/dev/null | tr -d '\r\n ')"
    [ "$out" = 0 ] && ROOT_OK=1
    [ "$ROOT_OK" = 1 ]
}

root_tweak_applicable() {
    case "$1" in
        phantom) [ "$ANDROID_SDK" -ge 31 ] ;;
        *) return 0 ;;
    esac
}

root_tweak_describe() { # prints the question's explanation
    case "$1" in
        phantom)
            plain "   Android 12+ kills the 'phantom' child processes of an app (signal 9) when"
            plain "   there are more than 32 or when they use too much CPU: long builds die for it."
            plain "   Benefit: cargo / rustc are no longer killed in the middle of a build."
            plain "   Risk   : none for the phone; Android's protection against runaway apps is off."
            ;;
        doze)
            plain "   Benefit: Android stops pausing Termux in the background (Doze, battery"
            plain "            optimisation), so a build keeps running with the screen off."
            plain "   Risk   : a little more battery use while Termux is busy."
            ;;
        inotify)
            plain "   Benefit: raises the file-watch limits (many tools and editors fail with"
            plain "            'no space left on device' / 'too many open files' on big projects)."
            plain "   Risk   : a few MB of kernel memory; the value returns to normal at reboot"
            plain "            unless a boot script is installed (asked later)."
            ;;
        oom)
            plain "   Benefit: when memory runs low, Android kills other apps before it kills a"
            plain "            running cargo / rustc (their priority is raised for the build)."
            plain "   Risk   : your root manager is asked (or shows a notice) at each build; if"
            plain "            memory is really exhausted, the phone may become sluggish."
            ;;
        swap)
            plain "   Benefit: a swap file gives the linker more room: big links stop being"
            plain "            killed for lack of RAM."
            plain "   Risk   : it uses several GB of storage and wears flash; many Android"
            plain "            kernels refuse swap files (then it is cleanly cancelled)."
            ;;
        perf)
            plain "   Benefit: the CPU runs at full speed ('performance' governor): builds are"
            plain "            faster."
            plain "   Risk   : the phone heats up and the battery drains faster; the system"
            plain "            may throttle anyway. Lasts until the next reboot only."
            ;;
    esac
}

# ---- individual tweaks: each saves the original value, changes, reads back ----
ROOT_ORIG_PHANTOM=""
ROOT_ORIG_PHANTOM_DC=""
ROOT_ORIG_APPOP=""
ROOT_ORIG_DOZE_ADDED=0
ROOT_ORIG_WATCHES=""
ROOT_ORIG_INSTANCES=""
ROOT_SWAP_FILE=""
ROOT_SWAP_MB=""
ROOT_ORIG_GOV=""
ROOT_BOOT_SCRIPT=""
ROOT_OOM_ADJ=""
ROOT_APPLIED="" # tweaks that really succeeded in this run

root_apply_phantom() {
    if [ "$ANDROID_SDK" -ge 32 ]; then
        ROOT_ORIG_PHANTOM="$(rsu 'settings get global settings_enable_monitor_phantom_procs' 2>/dev/null | tr -d '\r\n')"
        rsu 'settings put global settings_enable_monitor_phantom_procs false' >/dev/null 2>&1
        [ "$(rsu 'settings get global settings_enable_monitor_phantom_procs' 2>/dev/null | tr -d '\r\n')" = false ]
    else # Android 12 (API 31): only the "more than 32 processes" limit can be lifted
        ROOT_ORIG_PHANTOM_DC="$(rsu 'device_config get activity_manager max_phantom_processes' 2>/dev/null | tr -d '\r\n')"
        rsu 'device_config put activity_manager max_phantom_processes 2147483647' >/dev/null 2>&1
        [ "$(rsu 'device_config get activity_manager max_phantom_processes' 2>/dev/null | tr -d '\r\n')" = 2147483647 ]
    fi
}
root_revert_phantom() {
    local o dc
    if [ "$(conf_get RT_ORIG_PHANTOM_DC)" != "" ]; then
        dc="$(conf_get RT_ORIG_PHANTOM_DC)"
        if [ "$dc" = null ]; then
            rsu 'device_config delete activity_manager max_phantom_processes' >/dev/null 2>&1
        else rsu "device_config put activity_manager max_phantom_processes $dc" >/dev/null 2>&1; fi
    fi
    o="$(conf_get RT_ORIG_PHANTOM)"
    if [ -n "$o" ]; then
        if [ "$o" = null ]; then
            rsu 'settings delete global settings_enable_monitor_phantom_procs' >/dev/null 2>&1
        else rsu "settings put global settings_enable_monitor_phantom_procs $o" >/dev/null 2>&1; fi
    fi
    return 0
}

root_apply_doze() {
    local wl
    wl="$(rsu 'dumpsys deviceidle whitelist' 2>/dev/null)"
    if printf '%s' "$wl" | grep -q ",$TERMUX_PKG,"; then
        ROOT_ORIG_DOZE_ADDED=0
    else
        rsu "dumpsys deviceidle whitelist +$TERMUX_PKG" >/dev/null 2>&1
        ROOT_ORIG_DOZE_ADDED=1
    fi
    ROOT_ORIG_APPOP="$(rsu "cmd appops get $TERMUX_PKG RUN_ANY_IN_BACKGROUND" 2>/dev/null | head -n1 | sed -n 's/^RUN_ANY_IN_BACKGROUND: *\([a-z_]*\).*/\1/p')"
    [ -n "$ROOT_ORIG_APPOP" ] || ROOT_ORIG_APPOP=default
    rsu "cmd appops set $TERMUX_PKG RUN_ANY_IN_BACKGROUND allow" >/dev/null 2>&1
    rsu 'dumpsys deviceidle whitelist' 2>/dev/null | grep -q ",$TERMUX_PKG,"
}
root_revert_doze() {
    [ "$(conf_get RT_ORIG_DOZE_ADDED)" = 1 ] && rsu "dumpsys deviceidle whitelist -$TERMUX_PKG" >/dev/null 2>&1
    local m
    m="$(conf_get RT_ORIG_APPOP)"
    [ -n "$m" ] && rsu "cmd appops set $TERMUX_PKG RUN_ANY_IN_BACKGROUND $m" >/dev/null 2>&1
    return 0
}

root_apply_inotify() {
    ROOT_ORIG_WATCHES="$(rsu 'cat /proc/sys/fs/inotify/max_user_watches' 2>/dev/null | tr -d '\r\n')"
    ROOT_ORIG_INSTANCES="$(rsu 'cat /proc/sys/fs/inotify/max_user_instances' 2>/dev/null | tr -d '\r\n')"
    is_uint "$ROOT_ORIG_WATCHES" && is_uint "$ROOT_ORIG_INSTANCES" || return 1
    [ "$ROOT_ORIG_WATCHES" -ge 524288 ] || rsu 'echo 524288 > /proc/sys/fs/inotify/max_user_watches' >/dev/null 2>&1
    [ "$ROOT_ORIG_INSTANCES" -ge 1024 ] || rsu 'echo 1024 > /proc/sys/fs/inotify/max_user_instances' >/dev/null 2>&1
    [ "$(rsu 'cat /proc/sys/fs/inotify/max_user_watches' 2>/dev/null | tr -d '\r\n')" -ge 524288 ] 2>/dev/null
}
root_revert_inotify() {
    local w i
    w="$(conf_get RT_ORIG_WATCHES)"
    i="$(conf_get RT_ORIG_INSTANCES)"
    is_uint "$w" && rsu "echo $w > /proc/sys/fs/inotify/max_user_watches" >/dev/null 2>&1
    is_uint "$i" && rsu "echo $i > /proc/sys/fs/inotify/max_user_instances" >/dev/null 2>&1
    return 0
}

# Raised priority is applied by the fake cargo itself, at each build (see its code);
# here we only record the value it must use.
root_apply_oom() {
    ROOT_OOM_ADJ=-300
    return 0
}
root_revert_oom() { return 0; } # lives in ~/.rustup-fake/settings, which is removed

# root_apply_swap SIZE_MB LOGFILE  (slow: run through run_logged)
root_swap_create() {
    local mb="$1" f="/data/local/rust-termux.swap"
    ROOT_TIMEOUT=1800 rsu "swapoff $f 2>/dev/null; rm -f $f; dd if=/dev/zero of=$f bs=1048576 count=$mb && chmod 600 $f && mkswap $f && swapon $f"
}
root_apply_swap() { # after root_swap_create
    local f="/data/local/rust-termux.swap"
    # /proc/swaps shows the path relative to the mount ("/local/rust-termux.swap"), never "/data/local/...": match the file name
    if rsu 'cat /proc/swaps' 2>/dev/null | grep -q "${f##*/}"; then
        ROOT_SWAP_FILE="$f"
        return 0
    fi
    rsu "swapoff $f; rm -f $f" >/dev/null 2>&1
    return 1
}
root_revert_swap() {
    local f
    f="$(conf_get RT_SWAP_FILE)"
    [ -n "$f" ] || return 0
    rsu "swapoff $f; rm -f $f" >/dev/null 2>&1
    return 0
}

root_apply_perf() {
    local out="" p g avail ok=0
    for p in $(rsu 'ls -d /sys/devices/system/cpu/cpufreq/policy*' 2>/dev/null); do
        g="$(rsu "cat $p/scaling_governor" 2>/dev/null | tr -d '\r\n')"
        avail="$(rsu "cat $p/scaling_available_governors" 2>/dev/null)"
        [ -n "$g" ] || continue
        case " $avail " in *" performance "*) ;; *) continue ;; esac
        out="$out ${p##*/}:$g"
        rsu "echo performance > $p/scaling_governor" >/dev/null 2>&1
        [ "$(rsu "cat $p/scaling_governor" 2>/dev/null | tr -d '\r\n')" = performance ] && ok=1
    done
    ROOT_ORIG_GOV="${out# }"
    [ "$ok" = 1 ]
}
root_revert_perf() {
    local e
    for e in $(conf_get RT_ORIG_GOV); do
        rsu "echo ${e#*:} > /sys/devices/system/cpu/cpufreq/${e%%:*}/scaling_governor" >/dev/null 2>&1
    done
    return 0
}

# ---- boot script: re-applies what Android forgets at reboot (inotify, swap) -------
# It is a plain copy of $BASE/root-boot.sh; installed in a root-manager folder
# when one exists, otherwise in Termux:Boot's folder.
root_write_boot_script() { # $1 = list of applied tweaks
    local f="$BASE/root-boot.sh" t
    {
        echo '#!/system/bin/sh'
        echo '# Written by rustc-termux.sh: re-applies the tweaks Android'
        echo '# forgets at reboot. Removed by the uninstaller.'
        echo 'while [ "$(getprop sys.boot_completed)" != 1 ]; do sleep 5; done'
        echo 'sleep 20'
        for t in $1; do
            case "$t" in
                inotify)
                    echo '[ "$(cat /proc/sys/fs/inotify/max_user_watches)" -ge 524288 ] || echo 524288 > /proc/sys/fs/inotify/max_user_watches'
                    echo '[ "$(cat /proc/sys/fs/inotify/max_user_instances)" -ge 1024 ] || echo 1024 > /proc/sys/fs/inotify/max_user_instances'
                    ;;
                swap)
                    [ -n "$ROOT_SWAP_FILE" ] && echo "[ -f $ROOT_SWAP_FILE ] && swapon $ROOT_SWAP_FILE"
                    ;;
                phantom)
                    [ "$ANDROID_SDK" -lt 32 ] && echo 'device_config put activity_manager max_phantom_processes 2147483647'
                    ;;
            esac
        done
    } >"$f" 2>/dev/null || return 1
    [ "$(wc -l <"$f")" -gt 5 ] # something besides the header
}
root_install_boot_script() { # prints the destination on success
    local src="$BASE/root-boot.sh" dst
    if rsu '[ -d /data/adb/service.d ]' 2>/dev/null; then
        dst="/data/adb/service.d/$BOOT_SCRIPT_NAME"
        rsu "cp $src $dst && chmod 755 $dst" >/dev/null 2>&1 && rsu "[ -x $dst ]" 2>/dev/null && {
            echo "$dst"
            return 0
        }
    elif [ -d "$HOME/.termux/boot" ]; then
        dst="$HOME/.termux/boot/$BOOT_SCRIPT_NAME"
        {
            printf '#!/data/data/%s/files/usr/bin/bash\n' "$TERMUX_PKG"
            echo "su -c 'sh $src'"
        } >"$dst" 2>/dev/null &&
            chmod 700 "$dst" && {
            echo "$dst"
            return 0
        }
    fi
    return 1
}

# ---- everything applied earlier is put back (clean reinstall and uninstall) ----
# Needs PREV_CONF loaded. Returns 0 when nothing is left to undo by hand.
root_revert_from_conf() {
    local tw t bs rc=0
    tw="$(conf_get RT_ROOT_TWEAKS)"
    bs="$(conf_get RT_BOOT_SCRIPT)"
    [ -n "$tw" ] || [ -n "$bs" ] || return 0
    android_info
    info "Root tweaks applied earlier: ${tw:-none}"
    if ! detect_root; then
        warn "Root access is not available now: the earlier root tweaks cannot be reverted."
        plain "    They only last until the next reboot, except these which are stored by Android:"
        for t in $tw; do
            case "$t" in
                phantom) plain "    - phantom killer: adb/root: settings delete global settings_enable_monitor_phantom_procs" ;;
                doze) plain "    - Doze exemption: Settings > Apps > Termux > Battery > Optimised" ;;
                swap) plain "    - swap file $(conf_get RT_SWAP_FILE): root: swapoff it, then delete it" ;;
            esac
        done
        [ -n "$bs" ] && plain "    - boot script $bs: delete it with root"
        return 1
    fi
    for t in $tw; do
        case "$t" in
            phantom) root_revert_phantom ;;
            doze) root_revert_doze ;;
            inotify) root_revert_inotify ;;
            oom) root_revert_oom ;;
            swap) root_revert_swap ;;
            perf) root_revert_perf ;;
        esac
        ok "Root tweak reverted: $t"
    done
    if [ -n "$bs" ]; then
        case "$bs" in
            /data/adb/*) rsu "rm -f $bs" >/dev/null 2>&1 ;;
            *) rm -f "$bs" ;;
        esac
        ok "Boot script removed: $bs"
    fi
    return $rc
}

# Lines saved in the conf file (values found BEFORE the changes, for the revert)
root_conf_lines() {
    echo "# Root tweaks really applied (the uninstaller reverts them)"
    echo "RT_ROOT_TWEAKS=$(q "$ROOT_APPLIED")"
    echo "RT_ORIG_PHANTOM=$(q "$ROOT_ORIG_PHANTOM")"
    echo "RT_ORIG_PHANTOM_DC=$(q "$ROOT_ORIG_PHANTOM_DC")"
    echo "RT_ORIG_DOZE_ADDED=$ROOT_ORIG_DOZE_ADDED"
    echo "RT_ORIG_APPOP=$(q "$ROOT_ORIG_APPOP")"
    echo "RT_ORIG_WATCHES=$(q "$ROOT_ORIG_WATCHES")"
    echo "RT_ORIG_INSTANCES=$(q "$ROOT_ORIG_INSTANCES")"
    echo "RT_SWAP_FILE=$(q "$ROOT_SWAP_FILE")"
    echo "RT_ORIG_GOV=$(q "$ROOT_ORIG_GOV")"
    echo "RT_BOOT_SCRIPT=$(q "$ROOT_BOOT_SCRIPT")"
}

# ---------------------------------------------------------------------------
# Removal. The same functions serve the clean reinstall (default) and the
# uninstaller, so both erase exactly the same things.
# ---------------------------------------------------------------------------

# Removes our PATH block from the shell start-up files, plus the one-line
# forms written by earlier versions of these scripts.
remove_shell_integration() {
    local rc found=0 hasblock before after
    for rc in "${RC_FILES[@]}"; do
        [ -f "$rc" ] || continue
        grep -qE 'rust-termux|rustup-fake|rustup-proot|^# Faux rustup' "$rc" 2>/dev/null || continue
        found=1
        before="$(wc -l <"$rc")"
        cp -f "$rc" "$rc.rust-termux.bak" 2>/dev/null
        # A block is only removed as a whole when both of its markers are
        # present (a lone marker must never swallow the rest of the file).
        # The blank lines that surrounded our lines go away with them, so the
        # file comes back exactly as it was before the install.
        hasblock=0
        if grep -q '^# >>> rust-termux >>>$' "$rc" && grep -q '^# <<< rust-termux <<<$' "$rc"; then hasblock=1; fi
        awk -v b="$RC_BEGIN" -v e="$RC_END" -v hasblock="$hasblock" '
            function ours(l) { return l ~ /\.rustup-fake\/bin/ || l ~ /\.rustup-proot\/bin/ || l ~ /^# Faux rustup/ }
            {
                if (hasblock == 1) {
                    if (skip) { if ($0 == e) skip = 0; drop = 1; next }
                    if ($0 == b) { skip = 1; drop = 1; next }
                } else if ($0 == b || $0 == e) { drop = 1; next }
                if (ours($0)) { drop = 1; next }
                if ($0 ~ /^[[:space:]]*$/) { held[++run] = $0; next }
                n = run
                if (drop && n > 1) n = 1
                if (drop && !printed) n = 0
                for (i = 1; i <= n; i++) print held[i]
                print; printed = 1; run = 0; drop = 0
            }
            END { if (!drop) for (i = 1; i <= run; i++) print held[i] }
        ' "$rc" >"$rc.rust-termux.tmp" && cat "$rc.rust-termux.tmp" >"$rc"
        rm -f "$rc.rust-termux.tmp"
        after="$(wc -l <"$rc")"
        if grep -qE 'rustup-fake|rustup-proot|# >>> rust-termux >>>' "$rc" 2>/dev/null; then
            warn "Could not fully clean $rc: please check it by hand (backup: $rc.rust-termux.bak)."
        elif [ $((before - after)) -gt 12 ]; then
            warn "$rc lost $((before - after)) lines, more than expected: backup kept ($rc.rust-termux.bak)."
        else
            # Only our own lines went away: the safety copy is no longer needed.
            rm -f "$rc.rust-termux.bak"
            if ! grep -q '[^[:space:]]' "$rc" 2>/dev/null; then
                rm -f "$rc"
                ok "Shell configuration cleaned: $rc was left empty and has been removed"
            else
                ok "Shell configuration cleaned: $rc"
            fi
        fi
    done
    [ "$found" = 1 ] || info "No PATH entry found in the shell start-up files."
}

# Removes everything the installer itself created, except the saved settings,
# ~/.cargo and the Termux packages (those are handled by the callers).
remove_install_files() {
    local d src n=0 f
    # standard libraries the fake rustup built into Termux's own sysroot
    if [ -d "$BASE/std-installed" ]; then
        for f in "$BASE"/std-installed/*; do
            [ -f "$f" ] || continue
            rm -rf "$PREFIX/lib/rustlib/$(basename "$f")" && ok "Removed standard library: $(basename "$f")"
            n=$((n + 1))
        done
    fi
    for d in "$BASE" "$LEGACY_PROOT_BASE"; do
        [ -e "$d" ] || continue
        rm -rf "$d" 2>/dev/null
        if [ -e "$d" ]; then warn "Could not remove: $d"; else ok "Removed: $d"; fi
        n=$((n + 1))
    done

    # Rust sources extracted into Termux's own tree (unless a package owns them).
    src="$PREFIX/lib/rustlib/src"
    if [ -e "$src" ]; then
        if dpkg -S "$src" >/dev/null 2>&1; then
            info "The Rust sources belong to a Termux package: kept ($src)"
        else
            rm -rf "$src" 2>/dev/null
            if [ -e "$src" ]; then warn "Could not remove: $src"; else ok "Removed: $src"; fi
            n=$((n + 1))
        fi
    fi

    # Helper command from the very first script.
    if [ -f "$PREFIX/bin/cargo-wasm" ] && grep -q 'wasm32-unknown-unknown' "$PREFIX/bin/cargo-wasm" 2>/dev/null; then
        rm -f "$PREFIX/bin/cargo-wasm" && ok "Removed: $PREFIX/bin/cargo-wasm" && n=$((n + 1))
    fi

    # Test projects left behind by an interrupted run.
    for d in "$HOME"/.rust-termux-test.* "$HOME"/rust-test.*; do
        [ -d "$d" ] || continue
        case "$d" in
            */.rust-termux-test.*) ;;
            */rust-test.*) [ -d "$d/test-rust" ] || continue ;;
        esac
        rm -rf "$d" && ok "Removed leftover test directory: $d" && n=$((n + 1))
    done

    [ "$n" -gt 0 ] || info "No previous installation found."
    hash -r 2>/dev/null || true
    return 0
}

# Purges one package, but only if nothing else would be removed along with it.
purge_pkg_safe() {
    local p="$1" extra
    dpkg_installed "$p" || return 0
    extra="$(apt-get -s purge "$p" 2>/dev/null | awk '/^Remv /{print $2}' | grep -vxF "$p" | tr '\n' ' ')"
    if [ -n "${extra// /}" ]; then
        warn "Package '$p' is needed by: ${extra}- kept."
        return 2
    fi
    run_logged "$2" 20 "$LOG_DIR/apt_purge_$p.log" apt-get "${APT_OPTS[@]}" purge "$p"
}

# conf_load_quiet: make conf_get work for the commands that only read the settings.
conf_load_quiet() {
    PREV_CONF=0
    if [ -f "$CONF" ] && bash -n "$CONF" 2>/dev/null; then PREV_CONF=1; fi
}

# conf_set KEY VALUE: change (or add) one saved choice, quoted with %q.
conf_set() {
    local key="$1" val="$2" tmp="$CONF.tmp" line found=0
    touch "$CONF"
    : >"$tmp"
    while IFS= read -r line || [ -n "$line" ]; do
        case "$line" in
            "$key="*)
                printf '%s=%q\n' "$key" "$val" >>"$tmp"
                found=1
                ;;
            *) printf '%s\n' "$line" >>"$tmp" ;;
        esac
    done <"$CONF"
    [ "$found" = 1 ] || printf '%s=%q\n' "$key" "$val" >>"$tmp"
    mv -f "$tmp" "$CONF"
}
# --- tpf: end src/rustc-termux/common.sh ---
# --- tpf: begin src/rustc-termux/packs.sh ---
# Linker packs: what is needed to LINK programs for other platforms.

# ---------------------------------------------------------------------------
# Toolchain packs: what is needed to LINK programs for platforms other than the
# phone. Each pack is installed (compiled from source when needed), then checked
# by really building a program for one of its targets; a pack that fails the
# check is removed again, so nothing half-working is left.
# Everything lives in ~/.rustup-fake/toolchains (removed with the fake rustup).
# ---------------------------------------------------------------------------
TOOLS="$BASE/toolchains"
PACK_ALL="zig msvc ndk wasm"
PACKS_OK="" # packs installed AND verified in this run
PK_I=1
PK_N=1

pack_known() {
    case " $PACK_ALL " in *" $1 "*) return 0 ;; esac
    return 1
}

pack_describe() {
    case "$1" in
        zig)
            plain "   Zig + cargo-zigbuild: Linux (glibc and musl) and Windows (-gnu) programs from"
            plain "   the phone, macOS for pure-Rust code. Zig carries its own C libraries."
            plain "   Cost: the zig package (or the official tarball) + compiling cargo-zigbuild"
            plain "         (about 5-15 min), then one check build."
            ;;
        msvc)
            plain "   cargo-xwin: Windows MSVC programs (x86_64 / aarch64 *-pc-windows-msvc), linked"
            plain "   with clang + lld against the official Windows SDK/CRT, downloaded from Microsoft."
            plain "   Cost: compiling cargo-xwin (about 10-20 min) + a download of roughly 1 GB"
            plain "         (kept in ~/.rustup-fake/xwin-cache) + one check build."
            plain "   Requires accepting Microsoft's licence (asked separately)."
            ;;
        ndk)
            plain "   Termux's NDK multilib: Android programs for the OTHER CPU families"
            plain "   (armv7, x86, x86_64) linked with Termux's clang. EXPERIMENTAL: whether it"
            plain "   works depends on the files that package ships; the check build decides and"
            plain "   the pack is removed again if it fails."
            ;;
        wasm)
            plain "   WebAssembly tools: binaryen (wasm-opt), wabt (wasm2wat, ...), wasm-bindgen-cli."
            plain "   Cost: wasm-bindgen-cli is compiled from source (about 5-15 min)."
            ;;
    esac
}

# Targets registered (rustup target add) by each pack
pack_targets() {
    case "$1" in
        zig) echo "x86_64-unknown-linux-musl aarch64-unknown-linux-musl x86_64-unknown-linux-gnu aarch64-unknown-linux-gnu x86_64-pc-windows-gnu" ;;
        msvc) echo "x86_64-pc-windows-msvc aarch64-pc-windows-msvc" ;;
        ndk)
            local t
            for t in armv7-linux-androideabi i686-linux-android x86_64-linux-android aarch64-linux-android; do
                [ "$t" = "$HOST" ] || printf '%s ' "$t"
            done
            echo
            ;;
        *) echo "" ;;
    esac
}

pk_pct() { pct_at $(((PK_I - 1) * 10 + $1)) $((PK_N * 10)); } # step 1..10 of the current pack

# One Termux package for a pack. Remembers it if the installer is the one adding it.
pack_apt_one() { # pkg step [required]
    local p="$1" step="$2" had=1
    dpkg_installed "$p" || had=0
    if run_logged "$(pk_pct "$step")" 20 "$LOG_DIR/pack_apt_$p.log" apt-get "${APT_OPTS[@]}" install "$p"; then
        [ "$had" = 1 ] || PKGS_ADDED="${PKGS_ADDED:+$PKGS_ADDED }$p"
        ok "Package installed: $p"
        return 0
    fi
    return 1
}

pack_cargo_install() { # crate step expected_seconds [extra cargo install options]
    local crate="$1" step="$2" exp="$3"
    shift 3
    if run_logged "$(pk_pct "$step")" "$exp" "$LOG_DIR/pack_cargo_$crate.log" \
        env RUSTC="$REAL_RUSTC" ${JOBS:+CARGO_BUILD_JOBS=$JOBS} "$REAL_CARGO" install --locked --root "$TOOLS" "$@" "$crate"; then
        ok "Compiled and installed: $crate"
        return 0
    fi
    denied "Could not build $crate (see $LOG_DIR/pack_cargo_$crate.log):"
    tail -n 5 "$LOG_DIR/pack_cargo_$crate.log" 2>/dev/null | while IFS= read -r l; do plain "    $l"; done
    return 1
}

pack_add_targets() { # pack
    # Registered only: the standard library of these targets is built by cargo
    # at the first build (so the install does not build five of them for nothing).
    local t
    for t in $(pack_targets "$1"); do
        "$REAL_RUSTC" --print target-list | grep -qxF "$t" || continue
        grep -qxF "$t" "$BASE/targets" 2>/dev/null || echo "$t" >>"$BASE/targets"
    done
}

# Builds a hello-world for TARGET through the fake cargo and checks the file type.
#   pack_verify NAME TARGET magic(ELF|MZ) STEP EXPECTED_SECONDS
pack_verify() {
    local name="$1" t="$2" magic="$3" step="$4" exp="$5" bin got
    TEST_DIR="$(mktemp -d "$HOME/.rust-termux-test.XXXXXX")" || {
        warn "Cannot create a test directory."
        return 1
    }
    bin="$TEST_DIR/hello/target/$t/debug/hello"
    [ "$magic" = MZ ] && bin="$bin.exe"
    info "Check build for $t: the standard library is compiled, this takes several minutes."
    if run_logged "$(pk_pct "$step")" "$exp" "$LOG_DIR/pack_check_$name.log" \
        bash -c 'cd "$1" && env -u CARGO_TARGET_DIR cargo new --vcs none --quiet hello && cd hello && env -u CARGO_TARGET_DIR cargo build --quiet --target "$2"' _ "$TEST_DIR" "$t"; then
        if [ "$magic" = ELF ]; then got="$(head -c4 "$bin" 2>/dev/null | tail -c3)"; else got="$(head -c2 "$bin" 2>/dev/null)"; fi
        if [ "$got" = "$magic" ]; then
            ok "Check build passed: $t -> $(basename "$bin") ($magic)"
            rm -rf "$TEST_DIR"
            TEST_DIR=""
            return 0
        fi
        denied "The build for $t produced no valid $magic file."
    else
        denied "The check build for $t failed (see $LOG_DIR/pack_check_$name.log):"
        tail -n 8 "$LOG_DIR/pack_check_$name.log" 2>/dev/null | while IFS= read -r l; do plain "    $l"; done
    fi
    rm -rf "$TEST_DIR"
    TEST_DIR=""
    return 1
}

# A pack that failed its check leaves nothing behind.
pack_rollback() {
    local name="$1" t c
    for t in $(pack_targets "$name"); do
        grep -vxF "$t" "$BASE/targets" >"$BASE/targets.tmp" 2>/dev/null
        mv -f "$BASE/targets.tmp" "$BASE/targets" 2>/dev/null
    done
    case "$name" in
        zig) c="cargo-zigbuild" ;; msvc) c="cargo-xwin" ;; wasm) c="wasm-bindgen-cli" ;; *) c="" ;;
    esac
    [ -n "$c" ] && env RUSTC="$REAL_RUSTC" "$REAL_CARGO" uninstall --root "$TOOLS" "$c" >/dev/null 2>&1
    case "$name" in
        zig) rm -rf "$TOOLS/zig-dist" "$TOOLS/bin/zig" "$BASE/zig-cache" "$BASE/zigbuild-cache" ;;
        msvc) rm -rf "$BASE/xwin-cache" ;;
        ndk) rm -f "$TOOLS"/linkers/* ;;
    esac
    rm -f "$TOOLS/$name.installed"
}

# ---------------------------------------------------------------- zig ---------
# Termux's own package first; if it does not exist on this mirror, the official
# static tarball (checksum verified) is used.
pack_zig_tarball() {
    local plat idx ver url sum tmp got
    have jq || pack_apt_one jq 2 || {
        warn "jq is missing: cannot read ziglang.org's download index."
        return 1
    }
    case "$(uname -m)" in aarch64 | arm64) plat=aarch64-linux ;; x86_64) plat=x86_64-linux ;; armv7l | armv8l) plat=arm-linux ;; *) return 1 ;; esac
    tmp="$(mktemp -d)" || return 1
    if ! curl -fsSL --retry 3 --connect-timeout 20 -o "$tmp/index.json" https://ziglang.org/download/index.json; then
        rm -rf "$tmp"
        warn "ziglang.org is unreachable."
        return 1
    fi
    ver="$(jq -r 'keys[]' "$tmp/index.json" 2>/dev/null | grep -E '^[0-9]+\.[0-9]+\.[0-9]+$' | sort -V | tail -n1)"
    url="$(jq -r --arg v "$ver" --arg p "$plat" '.[$v][$p].tarball // empty' "$tmp/index.json" 2>/dev/null)"
    sum="$(jq -r --arg v "$ver" --arg p "$plat" '.[$v][$p].shasum // empty' "$tmp/index.json" 2>/dev/null)"
    if [ -z "$ver" ] || [ -z "$url" ] || [ -z "$sum" ]; then
        rm -rf "$tmp"
        warn "No Zig build listed for $plat."
        return 1
    fi
    info "Downloading Zig $ver ($plat)..."
    if ! run_logged "$(pk_pct 3)" 60 "$LOG_DIR/pack_zig_download.log" curl -fL --retry 3 --connect-timeout 20 -o "$tmp/zig.tar.xz" "$url"; then
        rm -rf "$tmp"
        warn "Zig download failed."
        return 1
    fi
    got="$(sha256sum "$tmp/zig.tar.xz" | awk '{print $1}')"
    if [ "$got" != "$sum" ]; then
        rm -rf "$tmp"
        denied "Zig checksum mismatch: download discarded."
        return 1
    fi
    ok "Zig checksum verified"
    mkdir -p "$TOOLS/zig-dist" "$TOOLS/bin"
    if ! tar -xJf "$tmp/zig.tar.xz" -C "$TOOLS/zig-dist" --strip-components=1; then
        rm -rf "$tmp" "$TOOLS/zig-dist"
        return 1
    fi
    ln -sf "$TOOLS/zig-dist/zig" "$TOOLS/bin/zig"
    rm -rf "$tmp"
    "$TOOLS/bin/zig" version >/dev/null 2>&1 || {
        rm -rf "$TOOLS/zig-dist" "$TOOLS/bin/zig"
        denied "The Zig binary does not run on this device."
        return 1
    }
    return 0
}

pack_install_zig() {
    local v
    export ZIG_GLOBAL_CACHE_DIR="$BASE/zig-cache" CARGO_ZIGBUILD_CACHE_DIR="$BASE/zigbuild-cache"
    mkdir -p "$ZIG_GLOBAL_CACHE_DIR" "$CARGO_ZIGBUILD_CACHE_DIR"
    if ! have zig; then
        pack_apt_one zig 2 || {
            info "No 'zig' package here: trying the official tarball."
            pack_zig_tarball || return 1
        }
    fi
    v="$(PATH="$TOOLS/bin:$PATH" zig version 2>/dev/null)" || {
        denied "zig is installed but does not run."
        return 1
    }
    ok "Zig works: $v"
    pack_cargo_install cargo-zigbuild 7 900 || return 1
    : >"$TOOLS/zig.installed"
    pack_add_targets zig
    pack_verify zig x86_64-unknown-linux-musl ELF 9 300 || return 1
    return 0
}

# ---------------------------------------------------------------- msvc --------
pack_install_msvc() {
    local p tool
    for p in clang lld openssl; do dpkg_installed "$p" || pack_apt_one "$p" 1 || {
        denied "Package '$p' is needed."
        return 1
    }; done
    pack_apt_one llvm 2 || warn "Package 'llvm' not installed: llvm-lib may be missing."
    mkdir -p "$TOOLS/bin"
    # clang and lld choose their personality from their file name
    have clang-cl || ln -sf "$(command -v clang)" "$TOOLS/bin/clang-cl"
    have lld-link || ln -sf "$(command -v lld)" "$TOOLS/bin/lld-link"
    if ! have llvm-lib; then have llvm-ar && ln -sf "$(command -v llvm-ar)" "$TOOLS/bin/llvm-lib"; fi
    for tool in clang-cl lld-link; do
        PATH="$TOOLS/bin:$PATH" command -v "$tool" >/dev/null 2>&1 && ok "Found: $tool" || {
            denied "$tool is missing."
            return 1
        }
    done
    # cargo-xwin's default TLS (rustls-platform-verifier) panics on Android: use the system OpenSSL.
    pack_cargo_install cargo-xwin 6 1200 --no-default-features --features native-tls ||
        {
            warn "native-tls build failed: trying the default features."
            pack_cargo_install cargo-xwin 6 1200 || return 1
        }
    export XWIN_CACHE_DIR="$BASE/xwin-cache"
    mkdir -p "$XWIN_CACHE_DIR"
    info "Downloading the Windows SDK and CRT from Microsoft (about 1 GB)..."
    if run_logged "$(pk_pct 8)" 300 "$LOG_DIR/pack_xwin_cache.log" \
        env PATH="$TOOLS/bin:$PATH" XWIN_CACHE_DIR="$XWIN_CACHE_DIR" RUSTC="$REAL_RUSTC" "$TOOLS/bin/cargo-xwin" xwin cache xwin; then
        ok "Windows SDK and CRT downloaded"
    else
        warn "SDK pre-download failed (see $LOG_DIR/pack_xwin_cache.log): it will be retried at the first build."
    fi
    : >"$TOOLS/msvc.installed"
    pack_add_targets msvc
    pack_verify msvc x86_64-pc-windows-msvc MZ 10 600 || return 1
    return 0
}

# ---------------------------------------------------------------- ndk ---------
ndk_clang_triple() {
    case "$1" in
        armv7-linux-androideabi) echo armv7a-linux-androideabi24 ;;
        *) echo "${1}24" ;;
    esac
}
ndk_dirname() {
    case "$1" in armv7-linux-androideabi) echo arm-linux-androideabi ;; *) echo "$1" ;; esac
}
pack_install_ndk() {
    local t d n=0 first=""
    pack_apt_one ndk-multilib 3 || {
        denied "The 'ndk-multilib' package is not available on this mirror."
        return 1
    }
    dpkg_installed ndk-sysroot || pack_apt_one ndk-sysroot 4 || true
    mkdir -p "$TOOLS/linkers"
    for t in $(pack_targets ndk); do
        d="$PREFIX/$(ndk_dirname "$t")"
        if [ ! -d "$d/lib" ] && [ ! -d "$d" ]; then
            warn "No libraries found for $t (expected $d)."
            continue
        fi
        {
            echo '#!/data/data/com.termux/files/usr/bin/bash'
            # rustc links with -nodefaultlibs: clang would not add the compiler-rt
            # builtins, which hold __emutls_get_address (std on 32-bit Android
            # uses emulated TLS). They are appended explicitly, after the objects.
            echo "exec clang --target=$(ndk_clang_triple "$t") --sysroot=$d -B$d/lib -L$d/lib -fuse-ld=lld \"\$@\" \"$(clang --target="$(ndk_clang_triple "$t")" --rtlib=compiler-rt --print-libgcc-file-name)\""
        } >"$TOOLS/linkers/$t"
        chmod +x "$TOOLS/linkers/$t"
        ok "Linker created for $t"
        n=$((n + 1))
        [ -n "$first" ] || first="$t"
    done
    [ "$n" -gt 0 ] || {
        denied "ndk-multilib installed nothing usable for cross-linking."
        return 1
    }
    : >"$TOOLS/ndk.installed"
    pack_add_targets ndk
    pack_verify ndk "$first" ELF 9 300 || return 1
    return 0
}

# ---------------------------------------------------------------- wasm --------
pack_install_wasm() {
    local good=0
    pack_apt_one binaryen 2 || warn "Package 'binaryen' (wasm-opt) is not available."
    pack_apt_one wabt 3 || warn "Package 'wabt' is not available."
    pack_cargo_install wasm-bindgen-cli 8 900 || return 1
    export PATH="$TOOLS/bin:$PATH"
    if "$TOOLS/bin/wasm-bindgen" --version >/dev/null 2>&1; then
        ok "wasm-bindgen: $("$TOOLS/bin/wasm-bindgen" --version 2>/dev/null)"
        good=1
    fi
    have wasm-opt && ok "wasm-opt: $(wasm-opt --version 2>/dev/null | head -n1)"
    [ "$good" = 1 ] || {
        denied "wasm-bindgen does not run."
        return 1
    }
    : >"$TOOLS/wasm.installed"
    return 0
}

# install_packs NAME...: installs and verifies each pack; a pack that fails its
# check is removed again. Adds the good ones to PACKS_OK and sets FAILED on failure.
install_packs() {
    local t
    mkdir -p "$TOOLS/bin" "$TOOLS/linkers"
    PK_N=$#
    PK_I=0
    for t in "$@"; do
        PK_I=$((PK_I + 1))
        plain ""
        plain "  ${C_INFO}Pack: $t${C_RESET}"
        if "pack_install_$t"; then
            ok "Pack ready and verified: $t"
            PACKS_OK="$PACKS_OK $t"
        else
            denied "Pack '$t' failed and was removed again."
            pack_rollback "$t"
            FAILED=1
        fi
    done
    PACKS_OK="${PACKS_OK# }"
}

# packs_add NAME... [--accept-msvc-license]: install packs into the existing
# install and change nothing else (settings, root tweaks, targets, other packs).
packs_add() {
    local t list="" licensed=0
    for t in "$@"; do
        case "$t" in
            --accept-msvc-license) licensed=1 ;;
            *)
                pack_known "$t" || die "Unknown pack: $t (known: $PACK_ALL)"
                if has_pack "$t"; then info "Pack already installed: $t"; else list="$list $t"; fi
                ;;
        esac
    done
    list="${list# }"
    [ -n "$list" ] || return 0
    [ -d "$(sysroot_dir)/lib/rustlib/src" ] || die "The Rust sources are missing: run '$TPF_SCRIPT reinstall' first."
    case " $list " in
        *" msvc "*)
            if [ "$licensed" = 1 ] || ask_yes_no "Do you accept Microsoft's licence (the Windows SDK and CRT are downloaded)?" no; then
                MSVC_LICENSE=1
            else
                warn "Licence not accepted: the 'msvc' pack is skipped."
                list="$(printf '%s' " $list " | sed 's/ msvc / /; s/^ *//; s/ *$//')"
            fi
            ;;
    esac
    [ -n "$list" ] || return 0
    wake_lock
    mkdir -p "$LOG_DIR"
    JOBS="$(setting jobs)"
    PACKS_OK=""
    PKGS_ADDED=""
    FAILED=0
    # shellcheck disable=SC2086
    install_packs $list
    conf_load_quiet
    local now added
    now="$(installed_packs)"
    conf_set RT_PACKS "${now% }"
    added="$(conf_get RT_PKGS_ADDED) $PKGS_ADDED"
    conf_set RT_PKGS_ADDED "$(printf '%s\n' $added | awk 'NF && !seen[$0]++' | tr '\n' ' ' | sed 's/ $//')"
    [ "$FAILED" = 0 ]
}
# --- tpf: end src/rustc-termux/packs.sh ---
# --- tpf: begin src/rustc-termux/uninstall.sh ---
# Removal of everything this tool wrote (cmd_uninstall) and of the root changes.

run_uninstall() {
    local added="" p list="" rm_pkgs=0 rm_rust=0 rm_conf=0 rm_data=0 n i hi

    phase_begin "Checking the environment" 5
    info "Mode: full UNINSTALL"
    mkdir -p "$LOG_DIR" 2>/dev/null
    strip_shims_from_path
    load_prev_conf
    added="$(conf_get RT_PKGS_ADDED)"
    [ -d "$BASE" ] && info "Fake rustup found: $BASE" || info "No fake rustup directory (leftovers will still be cleaned)."

    # ---- questions, all asked up front -----------------------------------
    phase_begin "Choosing what to remove" 5
    for p in $added; do
        case "$PROTECTED_PKGS" in *" $p "*) continue ;; esac
        dpkg_installed "$p" && list="$list $p"
    done
    list="${list# }"
    if [ -n "$list" ]; then
        info "Packages added by the installer and still installed: $list"
        ask_yes_no "Also remove these packages?" no && rm_pkgs=1
    else
        info "The installer added no package that is still installed."
    fi
    if dpkg_installed rust && ! { [ "$rm_pkgs" = 1 ] && [[ " $list " == *" rust "* ]]; }; then
        ask_yes_no "Also remove Termux's 'rust' package (compiler and cargo)?" no && rm_rust=1
    fi
    if [ "$PURGE_DATA" = 1 ]; then
        warn "--purge-data: saved settings and $CARGO_DATA_DIR will be deleted."
        if ask_yes_no "Confirm PERMANENT deletion of this data?" no; then
            rm_conf=1
            rm_data=1
        else info "Deletion cancelled, data kept."; fi
    else
        [ -f "$CONF" ] && ask_yes_no "Also delete the saved settings ($CONF)?" no && rm_conf=1
        if [ -d "$CARGO_DATA_DIR" ]; then
            warn "$CARGO_DATA_DIR holds the downloaded crates and the tools installed with 'cargo install'."
            ask_yes_no "Also delete $CARGO_DATA_DIR?" no && rm_data=1
        fi
    fi

    # ---- removal -----------------------------------------------------------
    phase_begin "Removing the fake rustup and its leftovers" 35
    # root changes first: the saved settings (and root access) are still needed for it
    root_revert_from_conf || warn "Some root changes could not be reverted automatically (see above)."
    remove_install_files
    phase_begin "Cleaning the shell configuration" 10
    remove_shell_integration

    phase_begin "Removing packages and data" 40
    if [ "$rm_pkgs" = 1 ] || [ "$rm_rust" = 1 ]; then
        # `rust` first: the other packages may be needed by it.
        local todo=()
        { [ "$rm_rust" = 1 ] || [[ " $list " == *" rust "* ]]; } && [ "$rm_pkgs$rm_rust" != "00" ] && todo+=(rust)
        if [ "$rm_pkgs" = 1 ]; then for p in $list; do [ "$p" = rust ] || todo+=("$p"); done; fi
        n=${#todo[@]}
        i=0
        for p in "${todo[@]}"; do
            i=$((i + 1))
            hi=$(pct_at "$i" "$n")
            if ! dpkg_installed "$p"; then continue; fi
            if purge_pkg_safe "$p" "$hi"; then ok "Package removed: $p"; else
                [ "$?" = 2 ] || { warn "Could not remove package '$p' (see $LOG_DIR/apt_purge_$p.log)."; }
            fi
        done
        apt_repair
    else
        info "Termux packages kept."
    fi
    if [ "$rm_data" = 1 ]; then rm -rf "$CARGO_DATA_DIR" && ok "Removed: $CARGO_DATA_DIR"; fi
    if [ "$rm_conf" = 1 ]; then rm -f "$CONF" "$CONF.bak" "$CONF.tmp" && ok "Removed: $CONF"; fi
    [ "$rm_conf" = 1 ] || [ ! -f "$CONF" ] || info "Settings kept: $CONF (used as defaults by a future install)"

    phase_begin "Finishing" 5
    rm -rf "$LOG_DIR"
    rmdir "$(dirname "$LOG_DIR")" 2>/dev/null || true # ~/.cache, only if it is now empty
    bar_set 100
    bar_finish
    plain ""
    plain "============================================================"
    plain " Uninstall complete"
    plain "============================================================"
    plain " Close and reopen Termux so that the PATH of the current session"
    plain " forgets ~/.rustup-fake/bin (or run: hash -r; exec bash)."
    if dpkg_installed rust; then
        plain " Termux's own 'rust' package is still installed: rustc and cargo"
        plain " keep working, without rustup or extra targets."
    fi
    plain "============================================================"
}

cmd_uninstall() {
    # "reinstall" keeps the saved settings and ~/.cargo: TPF_KEEP_DATA=1
    if [ "$TPF_KEEP_DATA" = 1 ]; then PURGE_DATA=0; fi
    wake_lock
    run_uninstall
}
# --- tpf: end src/rustc-termux/uninstall.sh ---
# --- tpf: begin src/rustc-termux/install.sh ---
# Installation, in phases (run in this order by cmd_install).

embed_rustup_sh() {
    cat <<'TPF_EOF_661EF53F912D'
#!/data/data/com.termux/files/usr/bin/bash
# rustup (fake) - installed by install-fake-rustup-termux.sh
# The real rustup cannot run on Android. This one offers the usual commands on
# top of the 'rust' package from Termux. Remove everything with:
#     rustup self uninstall
BASE="${RUSTUP_FAKE_HOME:-$HOME/.rustup-fake}"
# A target's standard library is usable only if its real .rlib files are there.
# Termux's rust package ships some Android targets (armv7, i686, x86_64) with
# .rmeta metadata files only: rustc then fails with "required to be available
# in rlib format". A bare directory is NOT enough.
std_ready() { compgen -G "$1/libcore-*.rlib" >/dev/null 2>&1; }
REAL_RUSTC="${RUSTUP_FAKE_REAL_RUSTC:-${PREFIX:-/data/data/com.termux/files/usr}/bin/rustc}"
REAL_CARGO="${RUSTUP_FAKE_REAL_CARGO:-${PREFIX:-/data/data/com.termux/files/usr}/bin/cargo}"
TARGETS_FILE="$BASE/targets"
STD_DIR="$BASE/std-installed"      # one marker per target whose standard library we built
mkdir -p "$BASE/bin" "$STD_DIR"
touch "$TARGETS_FILE"

err()     { printf 'rustup (fake): %s\n' "$*" >&2; }
setting() { sed -n "s/^$1=//p" "$BASE/settings" 2>/dev/null | head -n1; }
host_triple() { "$REAL_RUSTC" -vV | sed -n 's/^host: //p'; }
sysroot_dir() { "$REAL_RUSTC" --print sysroot; }

# rustc looks for "rust-lld" to link WebAssembly and bare-metal targets.
# Termux ships "lld": it is simply given the expected name.
ensure_lld() {
    local sr hostt lld
    sr="$(sysroot_dir)"; hostt="$(host_triple)"
    [ -x "$sr/lib/rustlib/$hostt/bin/rust-lld" ] && return 0
    [ -e "$BASE/bin/rust-lld" ] && return 0
    lld="$(command -v lld 2>/dev/null || true)"
    if [ -n "$lld" ]; then ln -sf "$lld" "$BASE/bin/rust-lld"; return 0; fi
    err "lld not found: install it with 'pkg install lld'."
    return 1
}

# The sources of the standard library, in the SAME version as rustc. Cargo
# rebuilds the standard library from them for every non-native target.
ensure_src() {
    local sr ver marker dist url tmp want got
    sr="$(sysroot_dir)"
    ver="$("$REAL_RUSTC" --version | awk '{print $2}')"
    marker="$BASE/rust-src-version"
    if [ -d "$sr/lib/rustlib/src/rust/library/core" ]; then
        if dpkg -S "$sr/lib/rustlib/src" >/dev/null 2>&1; then return 0; fi   # shipped by a package
        [ "$(cat "$marker" 2>/dev/null)" = "$ver" ] && return 0
    fi
    dist="${RUSTUP_DIST_SERVER:-https://static.rust-lang.org}"
    url="$dist/dist/rust-src-${ver}.tar.xz"
    tmp="$(mktemp -d)" || { err "cannot create a temporary directory"; return 1; }
    echo "Downloading the Rust ${ver} sources (a few tens of MB)..."
    if ! curl -fL -sS --retry 3 --connect-timeout 20 -o "$tmp/src.tar.xz" "$url"; then
        rm -rf "$tmp"; err "download failed: $url"; return 1
    fi
    if curl -fsSL --retry 2 --connect-timeout 20 -o "$tmp/src.sha256" "$url.sha256" 2>/dev/null; then
        want="$(awk '{print $1; exit}' "$tmp/src.sha256")"
        got="$(sha256sum "$tmp/src.tar.xz" | awk '{print $1}')"
        if [ -z "$want" ] || [ "$want" != "$got" ]; then
            rm -rf "$tmp"; err "checksum mismatch: the download is corrupted, try again"; return 1
        fi
        echo "Checksum verified."
    else
        echo "warning: no checksum available, integrity not verified" >&2
    fi
    if ! tar -xJf "$tmp/src.tar.xz" -C "$tmp"; then
        rm -rf "$tmp"; err "unreadable archive"; return 1
    fi
    rm -rf "$sr/lib/rustlib/src"
    mkdir -p "$sr/lib/rustlib"
    cp -r "$tmp"/rust-src-*/rust-src/lib/rustlib/src "$sr/lib/rustlib/"
    rm -rf "$tmp"
    if [ ! -d "$sr/lib/rustlib/src/rust/library/core" ]; then
        err "sources copied but not found where expected"; return 1
    fi
    echo "$ver" > "$marker"
    echo "Rust sources installed."
}

# Says honestly how far each kind of target can go on Termux.
has_pack() { [ -e "$BASE/toolchains/$1.installed" ]; }
target_hint() {
    local t="$1"
    case "$t" in
        *-unknown-linux-gnu|*-unknown-linux-musl|*-pc-windows-gnu*)
            if has_pack zig; then echo "  -> linked by Zig: 'cargo build --target $t' uses cargo-zigbuild automatically."; return; fi ;;
        *-apple-darwin|*-apple-ios*)
            if has_pack zig; then echo "  -> Zig can link pure-Rust code for macOS; system frameworks need a macOS SDK (set SDKROOT)."; return; fi ;;
        *-pc-windows-msvc)
            if has_pack msvc; then echo "  -> linked with clang/lld + the Windows SDK: 'cargo build --target $t' uses cargo-xwin automatically."; return; fi ;;
        armv7-linux-androideabi|i686-linux-android|x86_64-linux-android|aarch64-linux-android)
            if has_pack ndk; then echo "  -> linked with Termux's clang and ndk-multilib."; return; fi ;;
    esac
    case "$t" in
        wasm32-unknown-emscripten)
            echo "  -> needs Emscripten (emcc), not available on Termux: 'cargo check' works, linking does not." ;;
        wasm32-wasi*|wasm32-wasip*)
            echo "  -> needs a WASI C library that Termux does not provide: 'cargo check' works, linking may fail." ;;
        wasm32*|*-none|*-none-*)
            echo "  -> linked with lld: compiling and linking should both work." ;;
        x86_64-pc-windows-gnu|i686-pc-windows-gnu)
            echo "  -> no linker: 'cargo check' works, linking does not. Install the 'zig' pack to link it" \
                 "(re-run the installer with --toolchains zig)." ;;
        *-linux-android*)
            echo "  -> linking works for this phone's architecture only; other Android targets need the NDK." ;;
        *)
            echo "  -> no linker or system libraries for this target: 'cargo check --target $t' works,"
            echo "     the final link of 'cargo build' will fail (see the packs: installer --list-toolchains)." ;;
    esac
}

# Builds the standard library of a target from the Rust sources ONCE and puts it
# in the compiler's own sysroot, exactly where the real rustup puts it. Every
# tool then finds it (cargo, build scripts, wasm-pack...) without any special flag.
build_target_std() {
    local t="$1" sr ver tmp crates extra="" f n=0 dest jobs
    sr="$(sysroot_dir)"; ver="$("$REAL_RUSTC" --version)"
    tmp="$(mktemp -d)" || { err "cannot create a temporary directory"; return 1; }
    mkdir -p "$tmp/src"
    printf '[package]\nname = "rtstdprobe"\nversion = "0.0.0"\nedition = "2021"\n\n[lib]\npath = "src/lib.rs"\n\n[workspace]\n' > "$tmp/Cargo.toml"
    crates="std,panic_abort"
    if RUSTC_BOOTSTRAP=1 "$REAL_RUSTC" --print cfg --target "$t" 2>/dev/null | grep -q '^target_os="none"'; then
        crates="core,alloc"; extra="-Zbuild-std-features=compiler-builtins-mem"
        echo '#![no_std]' > "$tmp/src/lib.rs"
    else
        echo 'pub fn probe() {}' > "$tmp/src/lib.rs"
    fi
    echo "Building the standard library for $t (several minutes, once)..."
    jobs="$(setting jobs)"
    # The standard library must carry LLVM bitcode, like the one rustup ships: projects
    # that set `lto = true` fail otherwise ("Can't find section .llvmbc").
    if ! ( cd "$tmp" && env PATH="$BASE/bin:$PATH" RUSTC_BOOTSTRAP=1 RUSTC="$REAL_RUSTC" CARGO_TARGET_DIR="$tmp/target" \
             RUSTFLAGS="${RUSTFLAGS:+$RUSTFLAGS }-Cembed-bitcode=yes" \
             ${jobs:+CARGO_BUILD_JOBS=$jobs} "$REAL_CARGO" build --release --quiet --target "$t" "-Zbuild-std=$crates" $extra ) >"$tmp/build.log" 2>&1; then
        tail -n 15 "$tmp/build.log" >&2
        rm -rf "$tmp"; err "the standard library for $t could not be built"; return 1
    fi
    dest="$sr/lib/rustlib/$t/lib"
    rm -rf "$sr/lib/rustlib/$t"; mkdir -p "$dest"
    for f in "$tmp"/target/"$t"/release/deps/*.rlib; do
        [ -e "$f" ] || continue
        case "$(basename "$f")" in librtstdprobe*) continue ;; esac
        cp "$f" "$dest/" && n=$((n+1))
    done
    rm -rf "$tmp"
    if [ "$n" -eq 0 ]; then rm -rf "$sr/lib/rustlib/$t"; err "no library was produced for $t"; return 1; fi
    echo "$ver" > "$STD_DIR/$t"
    echo "Standard library for $t installed ($n libraries)."
}

cmd_target() {
    local sub="${1:-}"; shift || true
    local sr t list=() skip=0 a
    sr="$(sysroot_dir)"
    case "$sub" in
        add)
            for a in "$@"; do
                if [ "$skip" = 1 ]; then skip=0; continue; fi
                case "$a" in --toolchain) skip=1 ;; -*) ;; *) list+=("$a") ;; esac
            done
            [ "${#list[@]}" -gt 0 ] || { err "give a target: rustup target add TARGET_NAME"; return 1; }
            ensure_src || return 1
            ensure_lld || true
            for t in "${list[@]}"; do
                if ! "$REAL_RUSTC" --print target-list | grep -qxF "$t"; then
                    err "unknown target: $t  (see 'rustup target list')"; return 1
                fi
                if std_ready "$sr/lib/rustlib/$t/lib" && [ ! -f "$STD_DIR/$t" ]; then
                    echo "info: target $t is already available natively"; continue
                fi
                if [ "$(cat "$STD_DIR/$t" 2>/dev/null)" != "$("$REAL_RUSTC" --version)" ]; then
                    build_target_std "$t" || return 1
                fi
                grep -qxF "$t" "$TARGETS_FILE" || echo "$t" >> "$TARGETS_FILE"
                echo "info: target $t installed"
                target_hint "$t"
            done ;;
        remove)
            for t in "$@"; do
                case "$t" in -*) continue ;; esac
                grep -vxF "$t" "$TARGETS_FILE" > "$TARGETS_FILE.tmp" || true
                mv "$TARGETS_FILE.tmp" "$TARGETS_FILE"
                if [ -f "$STD_DIR/$t" ]; then rm -rf "$sr/lib/rustlib/$t"; rm -f "$STD_DIR/$t"; fi
                echo "info: target $t removed"
            done ;;
        list)
            if [ "${1:-}" = "--installed" ]; then
                for d in "$sr"/lib/rustlib/*/lib; do [ -d "$d" ] && basename "$(dirname "$d")"; done
                cat "$TARGETS_FILE"
            else
                while IFS= read -r t; do
                    if std_ready "$sr/lib/rustlib/$t/lib" || grep -qxF "$t" "$TARGETS_FILE"; then
                        echo "$t (installed)"
                    else
                        echo "$t"
                    fi
                done < <("$REAL_RUSTC" --print target-list)
            fi ;;
        *) err "usage: rustup target add|remove|list [--installed]"; return 1 ;;
    esac
}

cmd_toolchain() {
    local sub="${1:-}"; shift || true
    local a
    case "$sub" in
        list)
            echo "stable-$(host_triple) (default: provided by the Termux package)"
            if [ "$(setting nightly)" = 1 ]; then echo "nightly (simulated: stable compiler + RUSTC_BOOTSTRAP=1)"; fi ;;
        install)
            for a in "$@"; do
                case "$a" in
                    -*) ;;
                    stable*) echo "stable: already provided by Termux (update with 'rustup update')" ;;
                    nightly*)
                        if [ "$(setting nightly)" = 1 ]; then
                            echo "nightly: simulated mode is on. It is NOT a real nightly: it is the stable compiler"
                            echo "  of Termux with the flag that allows unstable features present in its version."
                            echo "  Use it with: cargo +nightly build"
                        else
                            err "the simulated nightly mode is off: run the installer again with --nightly"; return 1
                        fi ;;
                    beta*) echo "beta: not available on Termux, stable is used." ;;
                    *) err "toolchain '$a' unavailable: only stable and a simulated nightly exist here."; return 1 ;;
                esac
            done ;;
        uninstall) echo "Nothing to uninstall: the toolchain comes from the Termux package 'rust'." ;;
        *) err "usage: rustup toolchain list|install"; return 1 ;;
    esac
}

cmd_component() {
    local sub="${1:-}"; shift || true
    local c
    case "$sub" in
        add)
            for c in "$@"; do
                case "$c" in
                    -*|--toolchain) ;;
                    rust-src) ensure_src && echo "info: rust-src ready" ;;
                    rustfmt|rustfmt-preview)
                        if command -v rustfmt >/dev/null 2>&1; then echo "info: rustfmt already present"
                        else err "rustfmt is not part of the Termux 'rust' package on this device"; fi ;;
                    clippy|clippy-preview)
                        if command -v cargo-clippy >/dev/null 2>&1; then echo "info: clippy already present"
                        else err "clippy is not part of the Termux 'rust' package on this device"; fi ;;
                    rust-analyzer)
                        if command -v rust-analyzer >/dev/null 2>&1; then echo "info: rust-analyzer already present"
                        else err "rust-analyzer is not installed: try 'pkg install rust-analyzer'"; fi ;;
                    *) err "component '$c' not handled" ;;
                esac
            done ;;
        list) echo "rust-src (if installed)"; command -v cargo-clippy rustfmt rust-analyzer 2>/dev/null || true ;;
        *) err "usage: rustup component add rust-src|rustfmt|clippy|rust-analyzer"; return 1 ;;
    esac
}

cmd_self() {
    local sub="${1:-}"; shift || true
    case "$sub" in
        uninstall)
            local tool; tool="$(setting tool)"
            if [ -n "$tool" ] && [ -f "$tool" ]; then exec bash "$tool" uninstall "$@"; fi
            err "The rustc-termux.sh that installed this was not found: run '"'"'rustc-termux.sh uninstall'"'"' from where you saved it."; return 1 ;;
        update)
            echo "Run: rustc-termux.sh reinstall (it reinstalls everything cleanly)." ;;
        *) err "usage: rustup self uninstall|update"; return 1 ;;
    esac
}

case "${1:-}" in
    target)    shift; cmd_target "$@" ;;
    toolchain) shift; cmd_toolchain "$@" ;;
    component) shift; cmd_component "$@" ;;
    self)      shift; cmd_self "$@" ;;
    update)
        apt-get update >/dev/null 2>&1
        apt-get install -y --only-upgrade rust && ensure_src && ensure_lld
        for f in "$STD_DIR"/*; do
            [ -f "$f" ] || continue
            [ "$(cat "$f")" = "$("$REAL_RUSTC" --version)" ] || build_target_std "$(basename "$f")"
        done
        echo "Rust: $("$REAL_RUSTC" --version)" ;;
    default)
        shift
        case "${1:-}" in
            stable*|nightly*) echo "${1%%-*}" > "$BASE/default-toolchain"; echo "info: default toolchain: $1" ;;
            "") cat "$BASE/default-toolchain" 2>/dev/null || echo stable ;;
            *) err "unknown toolchain: $1"; exit 1 ;;
        esac ;;
    show)
        echo "Host: $(host_triple)"
        echo "Default toolchain: $(cat "$BASE/default-toolchain" 2>/dev/null || echo stable)"
        echo "Simulated nightly: $([ "$(setting nightly)" = 1 ] && echo on || echo off)"
        echo "Build jobs limit: $(setting jobs | sed 's/^$/none/')"
        echo "Raised build priority (root): $([ -n "$(setting oom)" ] && echo "on ($(setting oom))" || echo off)"
        echo "Linker packs: $(for p in zig msvc ndk wasm; do has_pack $p && printf '%s ' $p; done | sed 's/^$/none/')"
        echo "Targets added (standard library rebuilt when needed):"
        sed 's/^/  /' "$TARGETS_FILE"
        "$REAL_RUSTC" --version ;;
    run)
        shift
        tc="${1:-}"; shift || true
        case "$tc" in nightly*) export RUSTC_BOOTSTRAP=1 ;; esac
        exec "$@" ;;
    which) shift; command -v "${1:-rustc}" ;;
    --version|-V|version) echo "rustup 0.0.1 (fake rustup for Termux)" ;;
    ""|help|--help|-h)
        cat <<'EOT'
Fake rustup for Termux
  rustup target add|remove|list [--installed]
  rustup toolchain list|install nightly
  rustup component add rust-src|rustfmt|clippy|rust-analyzer
  rustup default stable|nightly
  rustup run nightly COMMAND
  rustup update | show | which
  rustup self uninstall
  (linker packs are chosen at install time: installer --list-toolchains)
EOT
        ;;
    *) err "unknown command: $1  (see 'rustup help')"; exit 1 ;;
esac
TPF_EOF_661EF53F912D
}
embed_cargo_sh() {
    cat <<'TPF_EOF_4D3B5DD1D684'
#!/data/data/com.termux/files/usr/bin/bash
# cargo (fake front-end) - installed by install-fake-rustup-termux.sh
# Runs Termux's cargo. For a target added with `rustup target add`, it also
# asks cargo to rebuild the standard library for that target.
BASE="${RUSTUP_FAKE_HOME:-$HOME/.rustup-fake}"
# A target's standard library is usable only if its real .rlib files are there.
# Termux's rust package ships some Android targets (armv7, i686, x86_64) with
# .rmeta metadata files only: rustc then fails with "required to be available
# in rlib format". A bare directory is NOT enough.
std_ready() { compgen -G "$1/libcore-*.rlib" >/dev/null 2>&1; }
REAL_CARGO="${RUSTUP_FAKE_REAL_CARGO:-${PREFIX:-/data/data/com.termux/files/usr}/bin/cargo}"
REAL_RUSTC="${RUSTUP_FAKE_REAL_RUSTC:-${PREFIX:-/data/data/com.termux/files/usr}/bin/rustc}"
setting() { sed -n "s/^$1=//p" "$BASE/settings" 2>/dev/null | head -n1; }

export PATH="$BASE/bin:$BASE/toolchains/bin:$PATH"   # "rust-lld", zig, cargo-zigbuild, cargo-xwin...
export RUSTC="$REAL_RUSTC"         # cargo uses the real rustc, not the fake one
# caches of the packs stay inside ~/.rustup-fake (removed with it)
export ZIG_GLOBAL_CACHE_DIR="${ZIG_GLOBAL_CACHE_DIR:-$BASE/zig-cache}"
export CARGO_ZIGBUILD_CACHE_DIR="${CARGO_ZIGBUILD_CACHE_DIR:-$BASE/zigbuild-cache}"
export XWIN_CACHE_DIR="${XWIN_CACHE_DIR:-$BASE/xwin-cache}"

if [ -z "${CARGO_BUILD_JOBS:-}" ]; then
    jobs="$(setting jobs)"
    [ -n "$jobs" ] && export CARGO_BUILD_JOBS="$jobs"
fi

args=("$@")
toolchain="$(cat "$BASE/default-toolchain" 2>/dev/null || echo stable)"
if [ "${#args[@]}" -gt 0 ] && [[ "${args[0]}" == +* ]]; then
    toolchain="${args[0]#+}"
    args=("${args[@]:1}")
fi
case "$toolchain" in
    nightly*)
        if [ "$(setting nightly)" != 1 ]; then
            echo "cargo (fake rustup): the simulated nightly mode is off. Run the installer again with --nightly." >&2
            exit 1
        fi
        export RUSTC_BOOTSTRAP=1 ;;
    stable*|beta*|"") ;;
    *) echo "cargo (fake rustup): toolchain '$toolchain' unavailable, Termux's stable is used." >&2 ;;
esac

# 1) find the sub-command (build, run, check...) past the global options
sub_i=-1; i=0
while [ "$i" -lt "${#args[@]}" ]; do
    case "${args[$i]}" in
        -C|--config|-Z|--color) i=$((i+2)) ;;
        -*) i=$((i+1)) ;;
        *) sub_i=$i; break ;;
    esac
done

# 2) list the requested targets (--target X or --target=X)
targets=()
if [ "$sub_i" -ge 0 ]; then
    case "${args[$sub_i]}" in
        build|b|check|c|run|r|test|t|bench|doc|d|rustc|rustdoc|clippy|fix|zigbuild|xwin)
            j=$((sub_i+1))
            while [ "$j" -lt "${#args[@]}" ]; do
                a="${args[$j]}"
                case "$a" in
                    --) break ;;
                    --target) targets+=("${args[$((j+1))]:-}"); j=$((j+2)); continue ;;
                    --target=*) targets+=("${a#--target=}") ;;
                esac
                j=$((j+1))
            done
            if [ "${#targets[@]}" -eq 0 ] && [ -n "${CARGO_BUILD_TARGET:-}" ]; then
                targets=("$CARGO_BUILD_TARGET")
            fi
            ;;
    esac
fi

# 3) for each target: native? added by 'rustup target add'? unknown?
need_std=()
if [ "${#targets[@]}" -gt 0 ]; then
    sysroot="$("$REAL_RUSTC" --print sysroot)"
    for t in "${targets[@]}"; do
        [ -z "$t" ] && continue
        case "$t" in *.json) need_std+=("$t"); continue ;; esac     # custom target file
        std_ready "$sysroot/lib/rustlib/$t/lib" && continue          # already available (real rlibs)
        if grep -qxF "$t" "$BASE/targets" 2>/dev/null; then
            need_std+=("$t")
        else
            echo "error: target '$t' is not installed." >&2
            echo "       Run first:  rustup target add $t" >&2
            exit 1
        fi
    done
fi

# 3b) linker packs: `cargo build --target X` goes through the right wrapper command
ins=$((sub_i+1))
if [ "$sub_i" -ge 0 ] && [ "${#targets[@]}" -gt 0 ]; then
    t0="${targets[0]}"
    case "${args[$sub_i]}" in
        build|b)
            case "$t0" in
                *-unknown-linux-gnu|*-unknown-linux-musl|*-pc-windows-gnu*|*-apple-darwin)
                    if [ -e "$BASE/toolchains/zig.installed" ] && [ -x "$BASE/toolchains/bin/cargo-zigbuild" ]; then
                        args[$sub_i]=zigbuild
                    fi ;;
                *-pc-windows-msvc)
                    if [ -e "$BASE/toolchains/msvc.installed" ] && [ -x "$BASE/toolchains/bin/cargo-xwin" ]; then
                        args=("${args[@]:0:$sub_i}" xwin build "${args[@]:$((sub_i+1))}"); ins=$((sub_i+2))
                    fi ;;
            esac ;;
        xwin) ins=$((sub_i+2)) ;;      # cargo xwin build ...
    esac
    # a standard library built for an older compiler would be rejected: rebuild it
    for t in "${targets[@]}"; do
        if [ -f "$BASE/std-installed/$t" ] && [ "$(cat "$BASE/std-installed/$t")" != "$("$REAL_RUSTC" --version)" ]; then
            "$BASE/bin/rustup" target add "$t" || exit 1
        fi
        # Zig supplies the C start-up files and libraries itself
        if [ -e "$BASE/toolchains/zig.installed" ]; then
            case "$t" in
                *-linux-musl*|*-windows-gnu*)
                    v="CARGO_TARGET_$(printf '%s' "$t" | tr 'a-z-' 'A-Z_')_RUSTFLAGS"
                    [ -n "${!v:-}" ] || export "$v=-Clink-self-contained=no" ;;
            esac
        fi
    done
    # linkers provided by a pack (one executable per target)
    for t in "${targets[@]}"; do
        [ -x "$BASE/toolchains/linkers/$t" ] || continue
        v="CARGO_TARGET_$(printf '%s' "$t" | tr 'a-z-' 'A-Z_')_LINKER"
        [ -n "${!v:-}" ] || export "$v=$BASE/toolchains/linkers/$t"
    done
fi

# 3c) root: raise the build's priority so Android kills other apps first
if [ "$sub_i" -ge 0 ]; then
    oomadj="$(setting oom)"
    if [ -n "$oomadj" ]; then
        case "${args[$sub_i]}" in
            build|b|check|c|run|r|test|t|bench|rustc|clippy|install|zigbuild|xwin)
                su_bin="$(command -v su 2>/dev/null)"
                [ -n "$su_bin" ] && timeout 10 env -u LD_LIBRARY_PATH -u LD_PRELOAD "$su_bin" -c "echo $oomadj > /proc/$$/oom_score_adj" >/dev/null 2>&1 </dev/null
                ;;
        esac
    fi
fi

# 4) added targets: cargo rebuilds the standard library itself
if [ "${#need_std[@]}" -gt 0 ]; then
    crates="std,panic_abort"; extra=()
    for t in "${need_std[@]}"; do
        if RUSTC_BOOTSTRAP=1 "$REAL_RUSTC" --print cfg --target "$t" 2>/dev/null | grep -q '^target_os="none"'; then
            crates="core,alloc"                                     # no operating system: no std
            extra=("-Zbuild-std-features=compiler-builtins-mem")
        fi
    done
    export RUSTC_BOOTSTRAP=1
    args=("${args[@]:0:$ins}" "-Zbuild-std=$crates" "${extra[@]}" "${args[@]:$ins}")
fi

exec "$REAL_CARGO" "${args[@]}"
TPF_EOF_4D3B5DD1D684
}
embed_rustc_sh() {
    cat <<'TPF_EOF_EFAD8DDEE374'
#!/data/data/com.termux/files/usr/bin/bash
# rustc (fake front-end) - handles `rustc +nightly ...`
BASE="${RUSTUP_FAKE_HOME:-$HOME/.rustup-fake}"
REAL_RUSTC="${RUSTUP_FAKE_REAL_RUSTC:-${PREFIX:-/data/data/com.termux/files/usr}/bin/rustc}"
export PATH="$BASE/bin:$PATH"
args=("$@")
toolchain="$(cat "$BASE/default-toolchain" 2>/dev/null || echo stable)"
if [ "${#args[@]}" -gt 0 ] && [[ "${args[0]}" == +* ]]; then
    toolchain="${args[0]#+}"
    args=("${args[@]:1}")
fi
case "$toolchain" in
    nightly*)
        if [ "$(sed -n 's/^nightly=//p' "$BASE/settings" 2>/dev/null | head -n1)" != 1 ]; then
            echo "rustc (fake rustup): the simulated nightly mode is off. Run the installer again with --nightly." >&2
            exit 1
        fi
        export RUSTC_BOOTSTRAP=1 ;;
esac
exec "$REAL_RUSTC" "${args[@]}"
TPF_EOF_EFAD8DDEE374
}
embed_gcc_sh() {
    cat <<'TPF_EOF_86C021401DC8'
#!/data/data/com.termux/files/usr/bin/bash
# GNU-style name for bare-metal ARM, provided by Termux's clang (written by install-fake-rustup-termux.sh).
exec clang --target=arm-none-eabi "$@"
TPF_EOF_86C021401DC8
}

# --- Bare-metal ARM tools ------------------------------------------------------------
# Many embedded projects expect GNU-named ARM tools (arm-none-eabi-gcc, -ar, ...) for the
# C code of their build scripts. Termux has no GNU ARM toolchain, so these names point to
# clang / llvm (which are installed anyway).
write_baremetal_tools() {
    local t
    mkdir -p "$BASE/bin" || return 1
    embed_gcc_sh >"$BASE/bin/arm-none-eabi-gcc"
    sed 's/exec clang /exec clang++ /' "$BASE/bin/arm-none-eabi-gcc" >"$BASE/bin/arm-none-eabi-g++"
    chmod +x "$BASE/bin/arm-none-eabi-gcc" "$BASE/bin/arm-none-eabi-g++"
    for t in ar ranlib objcopy objdump nm strip size readelf; do
        [ -x "$PREFIX/bin/llvm-$t" ] && ln -sf "$PREFIX/bin/llvm-$t" "$BASE/bin/arm-none-eabi-$t"
    done
    return 0
}

# --- PATH ---------------------------------------------------------------------------
# The fake tools must come first in the PATH. One marked block per start-up
# file, so that it can be removed exactly.
write_rc_block() {
    local rc="$1"
    [ -f "$rc" ] || : >"$rc"
    {
        echo ""
        echo "$RC_BEGIN"
        echo 'export PATH="$HOME/.rustup-fake/bin:$PATH"'
        echo "$RC_END"
    } >>"$rc"
}

# Checking the environment
phase_checking_the_environment() {
    ARCH="$(uname -m)"
    info "Architecture: $ARCH"
    info "Termux PREFIX: $PREFIX"
    if [ "$DO_RESET" = 1 ]; then
        info "Mode: clean reinstall (the current install is removed, then installed again)"
    else
        info "Mode: soft repair (--no-reset: what already works is kept)"
    fi
    [ "$PURGE_DATA" = 1 ] && warn "--purge-data: ~/.cargo and the saved settings will ALSO be deleted."

    case "$ARCH" in
        aarch64 | arm64) ok "Supported architecture ($ARCH)" ;;
        x86_64 | i686 | i386) ok "Architecture $ARCH (Termux on an emulator or a Chromebook)" ;;
        armv7l | armv8l | arm) warn "32-bit ARM: it should work, but builds are slow and memory-hungry." ;;
        *) warn "Untested architecture ($ARCH): it may work, no guarantee." ;;
    esac

    android_info
    if [ "$ANDROID_SDK" -gt 0 ]; then
        info "Android ${ANDROID_REL:-?} (API $ANDROID_SDK), Project Treble: ${TREBLE:-unknown}"
        if [ "$ANDROID_SDK" -lt 29 ]; then
            warn "Android older than 10: this installer targets recent devices (Treble, Android 10+); it may not work."
        elif [ "$TREBLE" = true ]; then
            ok "Recent Treble-compatible Android"
        else
            warn "Project Treble is not reported by this device: the script is designed for Treble devices."
        fi
    fi
    case "${TERMUX_APK_RELEASE:-}" in
        GOOGLE_PLAY_STORE) warn "This Termux comes from the Play Store (outdated, unmaintained): install the F-Droid or GitHub build." ;;
        "") [ -n "${TERMUX_VERSION:-}" ] || warn "Termux version unknown: an old Termux may lack recent packages. Update it from F-Droid/GitHub." ;;
        *) ok "Termux build: $TERMUX_APK_RELEASE ${TERMUX_VERSION:+(version $TERMUX_VERSION)}" ;;
    esac

    AVAIL_MB="$(df -Pm "$PREFIX" 2>/dev/null | awk 'NR==2 {print $4}')"
    if is_uint "${AVAIL_MB:-}"; then
        if [ "$AVAIL_MB" -lt 800 ]; then
            die "Not enough free space: ${AVAIL_MB} MB (about 2500 MB recommended)."
        elif [ "$AVAIL_MB" -lt 2500 ]; then
            warn "Low free space: ${AVAIL_MB} MB (about 2500 MB recommended; each target adds a few hundred MB)."
        else
            ok "Free space: ${AVAIL_MB} MB"
        fi
    fi

    if have curl; then
        if curl -sS -I --max-time 10 -o /dev/null https://static.rust-lang.org/ 2>"$LOG_DIR/network.log"; then
            ok "static.rust-lang.org is reachable"
        else
            warn "static.rust-lang.org is unreachable (see $LOG_DIR/network.log): the Rust sources cannot be downloaded."
        fi
    else
        info "curl is not installed yet: network check skipped."
    fi

    # Which packages are missing BEFORE anything changes: the uninstaller removes
    # only what this installer added, never what was already on the device.
    PRE_MISSING=""
    for p in "${DEPS_REQUIRED[@]}" "${DEPS_OPTIONAL[@]}"; do
        dpkg_installed "$p" || PRE_MISSING="$PRE_MISSING $p"
    done
    if [ -d "$BASE" ] || [ -d "$LEGACY_PROOT_BASE" ] || [ -f "$CONF" ]; then
        info "A previous installation was found."
    else
        info "No previous installation found."
    fi
}

# Choosing options
phase_choosing_options() {
    load_prev_conf

    PKGS_ADDED="$({
        for p in $(conf_get RT_PKGS_ADDED); do echo "$p"; done
        for p in $PRE_MISSING; do echo "$p"; done
    } |
        awk 'NF && !seen[$0]++' | tr '\n' ' ')"
    PKGS_ADDED="${PKGS_ADDED% }"

    # --- old proot-based script ---------------------------------------------------
    REMOVE_DEBIAN=0
    if [ -d "$LEGACY_PROOT_BASE" ] && have proot-distro; then
        warn "An older proot-based script left a Debian container behind (named 'debian')."
        plain "    This version does not use it. Removing it frees several GB."
        ask_yes_no "Remove it with 'proot-distro remove debian'?" no && REMOVE_DEBIAN=1
    fi

    # --- targets --------------------------------------------------------------------
    DEFAULT_TARGETS="wasm32-unknown-unknown"
    if [ "$NO_TARGETS" = 1 ]; then
        TARGETS=""
    elif [ -n "$TARGETS_ARG" ]; then
        TARGETS="$TARGETS_ARG"
    else
        cand="$DEFAULT_TARGETS"
        def=yes
        if conf_has RT_TARGETS; then
            saved="$(conf_get RT_TARGETS)"
            if [ -n "$saved" ]; then cand="$saved"; else def=no; fi
        fi
        plain "    Targets other than the phone's own use a standard library that is"
        plain "    rebuilt from source: the first build of each takes a few minutes."
        if ask_yes_no "Add the target(s) $cand now?" "$def"; then TARGETS="$cand"; else TARGETS=""; fi
    fi

    # --- simulated nightly -----------------------------------------------------------
    if [ "$ADD_PACKS" = 1 ]; then
        NIGHTLY="$(conf_get RT_NIGHTLY)"
        NIGHTLY="${NIGHTLY:-0}" # --add-packs changes nothing else
    elif [ -n "$NIGHTLY_ARG" ]; then
        NIGHTLY="$NIGHTLY_ARG"
    else
        plain ""
        warn "Optional: simulated nightly mode (\`cargo +nightly ...\`)."
        plain "   Benefit: unstable options (-Z...) and #![feature(...)] work."
        plain "   Risk   : it is NOT a real nightly, only Termux's compiler with the"
        plain "            RUSTC_BOOTSTRAP flag. Crates that detect \"nightly\" may switch on"
        plain "            code that this compiler does not have."
        if ask_yes_no "Enable the simulated nightly mode?" "$(prev_flag RT_NIGHTLY yes)"; then NIGHTLY=1; else NIGHTLY=0; fi
    fi

    # --- build jobs -------------------------------------------------------------------
    CPUS="$(nproc 2>/dev/null || echo 1)"
    is_uint "$CPUS" || CPUS=1
    MEM_MB="$(awk '/^MemTotal:/ {print int($2/1024)}' /proc/meminfo 2>/dev/null)"
    is_uint "${MEM_MB:-}" || MEM_MB=4096
    SUGGEST=$((MEM_MB / 1500))
    [ "$SUGGEST" -lt 1 ] && SUGGEST=1
    [ "$SUGGEST" -gt "$CPUS" ] && SUGGEST="$CPUS"
    SAVED_JOBS="$(conf_get RT_JOBS)"
    is_uint "${SAVED_JOBS:-}" && [ "$SAVED_JOBS" -ge 1 ] && SUGGEST="$SAVED_JOBS"
    JOBS=""
    if [ -n "$JOBS_ARG" ]; then
        [ "$JOBS_ARG" = 0 ] || JOBS="$JOBS_ARG"
    elif [ "$SUGGEST" -lt "$CPUS" ]; then
        jdef=yes
        if conf_has RT_JOBS && [ -z "$SAVED_JOBS" ]; then jdef=no; fi
        if ask_yes_no "Limit parallel build jobs to $SUGGEST ($CPUS cores, $MEM_MB MB RAM; too many jobs can make Android kill Termux)?" "$jdef"; then
            JOBS="$SUGGEST"
        fi
    else
        info "Build jobs: no limit needed ($CPUS cores, $MEM_MB MB RAM)."
    fi

    # --- root ---------------------------------------------------------------------------
    ROOT_SEL=""
    ROOT_BOOT=0
    SWAP_MB=""
    if [ "$ADD_PACKS" = 1 ]; then
        info "Root settings kept exactly as they are (--add-packs)."
    elif [ "$ROOT_MODE" = no ]; then
        info "Root not used (--no-root)."
    elif ! find_su && [ "$(id -u)" != 0 ]; then
        info "No root access on this device: normal, nothing is lost. Everything works without it."
    else
        info "A root manager was found. Checking access (it may ask you to allow Termux)..."
        if ! detect_root; then
            warn "Root was not granted (denied, or no answer): continuing without root."
        else
            ok "Root access granted ($([ "$(id -u)" = 0 ] && echo uid 0 || echo "$SU_BIN"))"
            saved_tw="$(conf_get RT_ROOT_TWEAKS)"
            plain "    Root can lift limits Android puts on long builds. Each tweak is explained,"
            plain "    can be refused, and is REVERTED by the uninstaller (the original values are"
            plain "    saved). SELinux and the system partition are never touched."
            if [ -n "$ROOT_TWEAKS_ARG" ]; then
                for t in $ROOT_TWEAKS_ARG; do
                    root_tweak_applicable "$t" && ROOT_SEL="$ROOT_SEL $t" || warn "Tweak '$t' does not apply to this Android (API $ANDROID_SDK): skipped."
                done
            elif [ "$ROOT_MODE" = yes ] || ask_yes_no "Use root to lift Android's limits for builds?" "$(prev_flag RT_USE_ROOT yes)"; then
                for t in $ROOT_ALL; do
                    root_tweak_applicable "$t" || {
                        info "Tweak '$t' does not apply to Android API $ANDROID_SDK."
                        continue
                    }
                    case "$ROOT_RISKY" in *" $t "*) risky=1 ;; *) risky=0 ;; esac
                    if [ "$ROOT_MODE" = yes ]; then # --root: the safe set only
                        [ "$risky" = 0 ] && ROOT_SEL="$ROOT_SEL $t"
                        continue
                    fi
                    plain ""
                    plain "  ${C_INFO}Root tweak: $t${C_RESET}"
                    root_tweak_describe "$t"
                    if [ "$risky" = 1 ] && [ "$TPF_ASSUME" = yes ]; then
                        info "'$t' is risky: --yes does not enable it (use --root-tweaks $t)."
                        continue
                    fi
                    if [ -n "$saved_tw" ]; then
                        case " $saved_tw " in *" $t "*) tdef=yes ;; *) tdef=no ;; esac
                    else [ "$risky" = 1 ] && tdef=no || tdef=yes; fi
                    ask_yes_no "Apply the '$t' tweak?" "$tdef" && ROOT_SEL="$ROOT_SEL $t"
                done
            fi
            ROOT_SEL="${ROOT_SEL# }"
            case " $ROOT_SEL " in
                *" swap "*)
                    FREE_DATA="$(df -Pm /data 2>/dev/null | awk 'NR==2 {print $4}')"
                    SWAP_MB="${SWAP_ARG:-2048}"
                    if is_uint "${FREE_DATA:-}" && [ "$FREE_DATA" -lt $((SWAP_MB + 3000)) ]; then
                        warn "Not enough free storage for a ${SWAP_MB} MB swap file (${FREE_DATA} MB free): swap skipped."
                        ROOT_SEL="$(printf '%s' " $ROOT_SEL " | sed 's/ swap / /; s/^ *//; s/ *$//')"
                    else info "Swap file size: ${SWAP_MB} MB"; fi
                    ;;
            esac
            # tweaks Android forgets at reboot
            case " $ROOT_SEL " in
                *" inotify "* | *" swap "*) need_boot=1 ;;
                *" phantom "*) [ "$ANDROID_SDK" -lt 32 ] && need_boot=1 || need_boot=0 ;;
                *) need_boot=0 ;;
            esac
            if [ "${need_boot:-0}" = 1 ]; then
                plain "    Some of these tweaks are forgotten by Android at reboot. A small boot script"
                plain "    (Magisk/KernelSU service.d, else Termux:Boot) can re-apply them."
                if [ "$TPF_ASSUME" = no ]; then ROOT_BOOT=0; else ask_yes_no "Re-apply them at every boot?" "$(prev_flag RT_ROOT_BOOT yes)" && ROOT_BOOT=1; fi
            fi
        fi
    fi
    [ -z "$ROOT_SEL" ] || info "Root tweaks chosen: $ROOT_SEL"

    # --- toolchain packs (linkers for other platforms) ------------------------------------
    PACKS=""
    MSVC_LICENSE=0
    SAVED_PACKS="$(conf_get RT_PACKS)"
    plain ""
    plain "  ${C_INFO}Linker packs${C_RESET}: link programs for other platforms (compiled from source if needed)."
    plain "  Not offered: Emscripten and the WASI C library (no native route on Android;"
    plain "  Emscripten would need a virtualised Linux, which this installer refuses to use)."
    if [ -n "$PACKS_ARG" ]; then
        [ "$PACKS_ARG" = none ] || PACKS="${PACKS_ARG//,/ }"
    elif [ "$TPF_ASSUME" = yes ]; then
        info "--yes does not install packs by itself (they are big): use --toolchains LIST."
    else
        for t in $PACK_ALL; do
            plain ""
            plain "  ${C_INFO}Pack: $t${C_RESET}"
            pack_describe "$t"
            case " $SAVED_PACKS " in *" $t "*) pdef=yes ;; *) pdef=no ;; esac
            ask_yes_no "Install the '$t' pack?" "$pdef" && PACKS="$PACKS $t"
        done
    fi
    PACKS="${PACKS# }"
    case " $PACKS " in
        *" msvc "*)
            plain ""
            warn "The 'msvc' pack downloads the Windows SDK and CRT from Microsoft."
            plain "    By using it you accept Microsoft's licence terms:"
            plain "    https://go.microsoft.com/fwlink/?LinkId=2086102 (Visual Studio) and the Windows SDK licence."
            if [ "$MSVC_LICENSE_ARG" = 1 ]; then
                MSVC_LICENSE=1
                info "Microsoft licence accepted (--accept-msvc-license)."
            elif [ "$TPF_ASSUME" != yes ] && ask_yes_no "Do you accept Microsoft's licence?" no; then MSVC_LICENSE=1; fi
            if [ "$MSVC_LICENSE" = 0 ]; then
                warn "Licence not accepted: the 'msvc' pack is skipped."
                PACKS="$(printf '%s' " $PACKS " | sed 's/ msvc / /; s/^ *//; s/ *$//')"
            fi
            ;;
    esac
    [ -z "$PACKS" ] || info "Packs chosen: $PACKS"

    # --- delete user data (only with --purge-data) -------------------------------------
    if [ "$PURGE_DATA" = 1 ]; then
        warn "This deletes: $CARGO_DATA_DIR (crate cache, tools from 'cargo install') and $CONF."
        if ask_yes_no "Confirm PERMANENT deletion of this data?" no; then :; else
            info "Deletion cancelled, data kept."
            PURGE_DATA=0
        fi
    fi

    info "Root tweaks: ${ROOT_SEL:-none}   Packs: ${PACKS:-none}"
    info "Targets: ${TARGETS:-none}   Nightly: $([ "$NIGHTLY" = 1 ] && echo simulated || echo off)   Build jobs: ${JOBS:-no limit}"
}

# Cleaning previous installations
phase_cleaning_previous_installation() {
    ROOT_CARRY=""
    if [ "$ADD_PACKS" = 1 ]; then
        ROOT_CARRY="$(grep -E '^(RT_ROOT_TWEAKS|RT_ORIG_[A-Z_]*|RT_SWAP_FILE|RT_BOOT_SCRIPT)=' "$CONF" 2>/dev/null)"
    elif ! root_revert_from_conf; then ROOT_CARRY="$(grep -E '^(RT_ROOT_TWEAKS|RT_ORIG_[A-Z_]*|RT_SWAP_FILE|RT_BOOT_SCRIPT)=' "$CONF" 2>/dev/null)"; fi
    if [ "$PURGE_DATA" = 1 ]; then
        rm -rf "$CARGO_DATA_DIR" && ok "Removed: $CARGO_DATA_DIR"
        rm -f "$CONF" "$CONF.bak" && ok "Removed: $CONF"
        PREV_CONF=0
    fi
    if [ "$DO_RESET" = 1 ]; then
        remove_shell_integration
        remove_install_files
    else
        info "Existing files kept (--no-reset)."
    fi
    if [ "$REMOVE_DEBIAN" = 1 ]; then
        if run_logged "$(pct_at 9 10)" 60 "$LOG_DIR/proot_remove.log" proot-distro remove debian; then
            ok "Debian container removed."
        else
            warn "Could not remove the Debian container (see $LOG_DIR/proot_remove.log)."
        fi
    fi
    mkdir -p "$BASE/bin" || die "Cannot create $BASE/bin"
    ok "Clean state ready"
}

# Updating Termux packages
phase_updating_termux_packages() {
    if [ "$SKIP_UPDATE" = 1 ]; then
        info "Package update skipped (--skip-update)."
    else
        apt_repair
        if run_logged "$(pct_at 1 3)" 25 "$LOG_DIR/apt_update.log" apt-get "${APT_OPTS[@]}" update; then
            ok "Repositories updated."
        else
            warn "apt update failed (see $LOG_DIR/apt_update.log)."
            warn "The mirror may be unreachable: run 'termux-change-repo', then run this script again."
        fi
        if run_logged "$(pct_at 3 3)" 60 "$LOG_DIR/apt_upgrade.log" apt-get "${APT_OPTS[@]}" upgrade; then
            ok "Packages upgraded."
        else
            warn "apt upgrade failed (see $LOG_DIR/apt_upgrade.log), continuing."
        fi
    fi
}

# Installing dependencies
phase_installing_dependencies() {
    n=$((${#DEPS_REQUIRED[@]} + ${#DEPS_OPTIONAL[@]}))
    i=0
    for p in "${DEPS_REQUIRED[@]}"; do
        i=$((i + 1))
        opts=()
        expected=15
        if [ "$p" = rust ]; then
            expected=90
            [ "$DO_RESET" = 1 ] && opts=(--reinstall)
        fi
        if ! run_logged "$(pct_at "$i" "$n")" "$expected" "$LOG_DIR/deps_$p.log" apt-get "${APT_OPTS[@]}" install "${opts[@]}" "$p"; then
            apt_repair
            run_logged "$(pct_at "$i" "$n")" "$expected" "$LOG_DIR/deps_$p.log" apt-get "${APT_OPTS[@]}" install "${opts[@]}" "$p" ||
                die "Failed to install '$p'. See $LOG_DIR/deps_$p.log"
        fi
        ok "Package installed: $p"
    done
    for p in "${DEPS_OPTIONAL[@]}"; do
        i=$((i + 1))
        if run_logged "$(pct_at "$i" "$n")" 15 "$LOG_DIR/deps_$p.log" apt-get "${APT_OPTS[@]}" install "$p"; then
            ok "Package installed: $p (optional)"
        else
            warn "Optional package '$p' could not be installed (see $LOG_DIR/deps_$p.log)."
        fi
    done

    hash -r 2>/dev/null || true
    RUST_VER="$("$REAL_RUSTC" --version 2>"$LOG_DIR/rustc_health.log")" ||
        die "The Termux 'rust' package is broken: $(head -n1 "$LOG_DIR/rustc_health.log" 2>/dev/null)"
    CARGO_VER="$("$REAL_CARGO" --version 2>>"$LOG_DIR/rustc_health.log")" ||
        die "cargo does not run (see $LOG_DIR/rustc_health.log)"
    HOST="$("$REAL_RUSTC" -vV 2>/dev/null | sed -n 's/^host: //p')"
    ok "Compiler works: $RUST_VER"
    ok "Cargo works: $CARGO_VER"
    info "Host target: $HOST"
}

# Creating the fake rustup
phase_creating_the_fake_rustup() {
    # --- rustup ---------------------------------------------------------------------
    embed_rustup_sh >"$BASE/bin/rustup" || die "Cannot write $BASE/bin/rustup"

    # --- cargo ----------------------------------------------------------------------
    embed_cargo_sh >"$BASE/bin/cargo" || die "Cannot write $BASE/bin/cargo"

    # --- rustc ----------------------------------------------------------------------
    embed_rustc_sh >"$BASE/bin/rustc" || die "Cannot write $BASE/bin/rustc"

    chmod +x "$BASE/bin/rustup" "$BASE/bin/cargo" "$BASE/bin/rustc" || die "Cannot make the fake tools executable."
    OOM_ADJ=""
    case " $ROOT_SEL " in *" oom "*) OOM_ADJ=-300 ;; esac
    [ "$ADD_PACKS" != 1 ] || OOM_ADJ="$(sed -n 's/^oom=//p' "$BASE/settings" 2>/dev/null | head -n1)" # keep the value of the earlier install
    printf 'nightly=%s\njobs=%s\noom=%s\ntool=%s\n' "$NIGHTLY" "$JOBS" "$OOM_ADJ" "$SELF" >"$BASE/settings" || die "Cannot write $BASE/settings"
    if have lld; then ln -sf "$(command -v lld)" "$BASE/bin/rust-lld"; else warn "lld not found: WebAssembly linking will not work."; fi
    ok "Fake rustup, cargo and rustc: $BASE/bin"

    if have clang && write_baremetal_tools; then
        ok "Bare-metal ARM tools: arm-none-eabi-gcc / ar / objcopy ... (clang + llvm)"
    else
        warn "Could not create the arm-none-eabi-* tools (clang missing?)."
    fi
    bar_set "$(pct_at 1 2)"

    remove_shell_integration >/dev/null # no duplicates, whatever the previous state was
    for rc in "${RC_FILES[@]}"; do
        case "$rc" in
            */.zshrc) if [ -f "$rc" ] || have zsh; then write_rc_block "$rc" && ok "PATH added to $rc"; fi ;;
            *) write_rc_block "$rc" && ok "PATH added to $rc" || warn "Could not write $rc" ;;
        esac
    done
    export PATH="$BASE/bin:$PATH"
    hash -r 2>/dev/null || true
}

# Installing the Rust standard library sources
phase_installing_the_rust_standard_l() {
    RUST_SRC_OK=1
    if run_logged "$(pct_at 1 1)" 40 "$LOG_DIR/rust_src.log" "$BASE/bin/rustup" component add rust-src; then
        ok "Rust sources installed (they match $RUST_VER)"
    else
        RUST_SRC_OK=0
        FAILED=1
        denied "The Rust sources could not be installed (see $LOG_DIR/rust_src.log):"
        tail -n 5 "$LOG_DIR/rust_src.log" 2>/dev/null | while IFS= read -r l; do plain "    $l"; done
        warn "Without them, only the phone's own target works. Run 'rustup target add ...' later to retry."
    fi
}

# Adding targets
phase_adding_targets() {
    ADDED_TARGETS=""
    if [ -z "$TARGETS" ]; then
        info "No target requested."
    elif [ "$RUST_SRC_OK" = 0 ]; then
        denied "Targets skipped: the Rust sources are missing."
    else
        IFS=',' read -r -a tlist <<<"$TARGETS"
        n=${#tlist[@]}
        i=0
        for t in "${tlist[@]}"; do
            [ -n "$t" ] || continue
            i=$((i + 1))
            if run_logged "$(pct_at "$i" "$n")" 240 "$LOG_DIR/target_$t.log" "$BASE/bin/rustup" target add "$t"; then
                ok "Target added: $t"
                ADDED_TARGETS="$ADDED_TARGETS $t"
                grep -- '->' "$LOG_DIR/target_$t.log" 2>/dev/null | while IFS= read -r l; do plain "   ${C_DIM}${l#  }${C_RESET}"; done
            else
                denied "Target refused: $t ($(tail -n 1 "$LOG_DIR/target_$t.log" 2>/dev/null))"
            fi
        done
    fi
    ADDED_TARGETS="${ADDED_TARGETS# }"
}

# Applying root tweaks
phase_applying_root_tweaks() {
    ROOT_GOOD=""
    if [ -z "$ROOT_SEL" ]; then
        info "No root tweak requested."
    else
        n=$(echo $ROOT_SEL | wc -w)
        i=0
        for t in $ROOT_SEL; do
            i=$((i + 1))
            ROOT_APPLIED="$ROOT_APPLIED $t" # recorded even if it fails: the revert is harmless
            if [ "$t" = swap ]; then
                info "Creating the ${SWAP_MB} MB swap file (this can take a few minutes)..."
                if run_logged "$(pct_at "$i" "$n")" 120 "$LOG_DIR/root_swap.log" root_swap_create "$SWAP_MB" && root_apply_swap; then
                    ok "Root tweak applied: swap (${SWAP_MB} MB, $ROOT_SWAP_FILE)"
                    ROOT_SWAP_MB="$SWAP_MB"
                    ROOT_GOOD="$ROOT_GOOD $t"
                else
                    denied "swap: this kernel refused the swap file (see $LOG_DIR/root_swap.log); it was removed again."
                    tail -n 3 "$LOG_DIR/root_swap.log" 2>/dev/null | while IFS= read -r l; do plain "    $l"; done
                    ROOT_APPLIED="${ROOT_APPLIED% swap}"
                fi
                continue
            fi
            if "root_apply_$t"; then
                ok "Root tweak applied: $t"
                ROOT_GOOD="$ROOT_GOOD $t"
            else denied "Root tweak not applied: $t (the value did not change; nothing kept)"; fi
            bar_set "$(pct_at "$i" "$n")"
        done
        ROOT_APPLIED="${ROOT_APPLIED# }"
        ROOT_GOOD="${ROOT_GOOD# }"
        if [ "$ROOT_BOOT" = 1 ] && [ -n "$ROOT_GOOD" ]; then
            if root_write_boot_script "$ROOT_GOOD"; then
                if dst="$(root_install_boot_script)"; then
                    ROOT_BOOT_SCRIPT="$dst"
                    ok "Boot script installed: $dst"
                else
                    warn "No boot-script folder found (/data/adb/service.d or ~/.termux/boot): the tweaks last until reboot."
                    plain "    Re-apply by hand with:  su -c 'sh $BASE/root-boot.sh'"
                fi
            else info "Nothing to re-apply at boot."; fi
        fi
    fi
}

# Installing linker packs
phase_installing_linker_packs() {
    if [ -z "$PACKS" ]; then
        info "No pack requested."
    elif [ "$RUST_SRC_OK" = 0 ]; then
        denied "Packs skipped: they need the Rust sources, which are missing."
        FAILED=1
    else
        install_packs $PACKS
    fi
    if [ "$ADD_PACKS" = 1 ]; then # packs installed earlier stay recorded
        for t in $SAVED_PACKS; do
            case " $PACKS_OK " in *" $t "*) ;; *) [ -e "$TOOLS/$t.installed" ] && PACKS_OK="${PACKS_OK:+$PACKS_OK }$t" ;; esac
        done
    fi

    # --- save the choices as defaults for the next run ---------------------------------------
    # Only packages that are really installed now are recorded for the uninstaller.
    PKGS_RECORDED=""
    for p in $PKGS_ADDED; do dpkg_installed "$p" && PKGS_RECORDED="$PKGS_RECORDED $p"; done
    PKGS_ADDED="${PKGS_RECORDED# }"
    (
        umask 077
        cat >"$CONF.tmp" <<EOF
# ============================================================================
# Choices saved by $TPF_SCRIPT $TPF_VERSION
# The next run of the installer uses them as its defaults.
# The fake tools read their own copy in ~/.rustup-fake/settings instead.
# ============================================================================

# Targets added at install time (comma-separated, empty = none)
RT_TARGETS=$(q "${TARGETS}")
# Simulated nightly mode (0/1)
RT_NIGHTLY=$NIGHTLY
# Limit on parallel build jobs (empty = no limit)
RT_JOBS=$(q "$JOBS")
# Termux packages added by the installer: the uninstaller removes only these
RT_PKGS_ADDED=$(q "$PKGS_ADDED")
# Linker packs installed and verified
RT_PACKS=$(q "$PACKS_OK")
# Root was used (0/1) and the boot script was wanted (0/1)
RT_USE_ROOT=$(if [ "$ADD_PACKS" = 1 ]; then
            conf_get RT_USE_ROOT
            [ -n "$(conf_get RT_USE_ROOT)" ] || echo 0
        elif [ -n "$ROOT_SEL" ]; then echo 1; else echo 0; fi)
RT_ROOT_BOOT=$(if [ "$ADD_PACKS" = 1 ]; then
            conf_get RT_ROOT_BOOT
            [ -n "$(conf_get RT_ROOT_BOOT)" ] || echo 0
        else echo $ROOT_BOOT; fi)

$(if [ -n "$ROOT_CARRY" ]; then
            echo "# Earlier root changes that could not be reverted (kept for the uninstaller)"
            echo "$ROOT_CARRY"
        else root_conf_lines; fi)
EOF
    ) && mv -f "$CONF.tmp" "$CONF" && ok "Choices saved: $CONF" || warn "Could not write $CONF"
}

# Testing the installation
phase_testing_the_installation() {
    for t in rustup cargo rustc; do
        if [ "$(command -v "$t")" = "$BASE/bin/$t" ]; then
            ok "'$t' resolves to the fake one"
        else
            warn "'$t' resolves to $(command -v "$t" || echo nothing): open a new Termux session."
        fi
    done
    if "$BASE/bin/cargo" +nightly --version >/dev/null 2>&1; then
        ok "cargo +nightly: $("$BASE/bin/cargo" +nightly --version 2>/dev/null)"
    elif [ "$NIGHTLY" = 1 ]; then
        denied "cargo +nightly does not work."
        FAILED=1
    else
        info "Simulated nightly mode is off."
    fi

    if [ "$NO_TEST" = 1 ]; then
        info "Compile tests skipped (--no-test)."
    else
        TEST_DIR="$(mktemp -d "$HOME/.rust-termux-test.XXXXXX")" || die "Cannot create a test directory in $HOME"
        if run_logged "$(pct_at 1 3)" 60 "$LOG_DIR/test_native.log" \
            bash -c 'cd "$1" && env -u CARGO_TARGET_DIR cargo new --vcs none --quiet hello && cd hello && env -u CARGO_TARGET_DIR cargo run --quiet' _ "$TEST_DIR" &&
            grep -q 'Hello, world!' "$LOG_DIR/test_native.log"; then
            ok "Native build and run: Hello, world!"
        else
            denied "The native test failed (see $LOG_DIR/test_native.log):"
            tail -n 8 "$LOG_DIR/test_native.log" 2>/dev/null | while IFS= read -r l; do plain "    $l"; done
            FAILED=1
        fi

        T1="${ADDED_TARGETS%% *}"
        if [ -z "$T1" ]; then
            info "No target to test."
        else
            case "$T1" in
                *-none | *-none-*)
                    info "Target $T1 has no standard library: build test skipped."
                    T1=""
                    ;;
            esac
        fi
        if [ -n "$T1" ] && [ "$FAILED" = 0 ]; then
            case "$T1" in wasm32-unknown-unknown) mode=build ;; *) mode=check ;; esac
            info "Testing target $T1 ('cargo $mode'): the standard library is compiled, this takes several minutes."
            if run_logged "$(pct_at 3 3)" 240 "$LOG_DIR/test_target.log" \
                bash -c 'cd "$1/hello" && env -u CARGO_TARGET_DIR cargo "$2" --quiet --target "$3"' _ "$TEST_DIR" "$mode" "$T1"; then
                if [ "$mode" = build ]; then
                    if ls "$TEST_DIR"/hello/target/"$T1"/debug/*.wasm >/dev/null 2>&1; then
                        ok "Target $T1: compiled and linked ($(ls "$TEST_DIR"/hello/target/"$T1"/debug/*.wasm | head -n1 | xargs basename))"
                    else
                        warn "Target $T1: the build succeeded but no .wasm file was produced."
                    fi
                else
                    ok "Target $T1: 'cargo check' passed (linking is not available on Termux for this target)"
                fi
            else
                denied "The test for target $T1 failed (see $LOG_DIR/test_target.log):"
                tail -n 8 "$LOG_DIR/test_target.log" 2>/dev/null | while IFS= read -r l; do plain "    $l"; done
                FAILED=1
            fi
        fi
        rm -rf "$TEST_DIR"
        TEST_DIR=""
    fi

    # ---------------------------------------------------------------------------
    # Summary
    # ---------------------------------------------------------------------------
    bar_set 100
    if [ "$FAILED" = 0 ]; then
        banner "Installation complete and verified" "$RUST_VER"
    else
        banner "Installation finished WITH PROBLEMS" "see the lines above"
    fi
    echo " Compiler      : $RUST_VER"
    echo " Cargo         : $CARGO_VER"
    echo " Host          : $HOST"
    echo " Targets added : ${ADDED_TARGETS:-none}"
    echo " Nightly mode  : $([ "$NIGHTLY" = 1 ] && echo "ENABLED (simulated)" || echo disabled)"
    echo " Build jobs    : ${JOBS:-no limit}"
    echo " Root tweaks   : ${ROOT_GOOD:-none}"
    echo " Linker packs  : ${PACKS_OK:-none}"
    echo "------------------------------------------------------------"
    echo " Commands      : rustup | cargo | rustc   ($BASE/bin)"
    echo " Choices       : $CONF"
    echo " Manage        : $TPF_SCRIPT status | doctor | packs | linker | targets | log"
    echo " Uninstall     : $TPF_SCRIPT uninstall    (or: rustup self uninstall)"
    echo " Install logs  : $LOG_DIR"
    echo "------------------------------------------------------------"
    echo " Notes:"
    echo " - Open a new Termux session (or run: source ~/.bashrc) so that the"
    echo "   PATH change takes effect."
    echo " - Running this script again cleanly reinstalls everything; your choices"
    echo "   are kept as defaults, and ~/.cargo is kept (unless --purge-data)."
    echo " - The first build for each added target compiles the standard library"
    echo "   (several minutes); later builds are fast."
    echo " - Add targets later:  rustup target add TARGET_NAME"
    [ -z "$PACKS_OK" ] || echo " - Cross builds: cargo build --target TARGET (the right linker is chosen for you)"
    echo " - Not provided: Emscripten (would need a virtualised Linux) and WASI linking."
    [ -z "$ROOT_GOOD" ] || echo " - Root changes are undone by the uninstaller (original values are saved)."
    echo " - Full help: $TPF_SCRIPT help"
    echo "============================================================"

    [ "$FAILED" = 0 ]
}

cmd_install() {
    validate_options
    check_termux
    mkdir -p "$LOG_DIR" || die "Cannot create $LOG_DIR"
    chmod 700 "$LOG_DIR" 2>/dev/null || true
    rm -f "$LOG_DIR"/*.log 2>/dev/null
    strip_shims_from_path
    banner "Rust for Termux (fake rustup)" "install v$TPF_VERSION"
    wake_lock
    phase_checking_the_environment
    phase_choosing_options
    phase_cleaning_previous_installation
    phase_updating_termux_packages
    phase_installing_dependencies
    phase_creating_the_fake_rustup
    phase_installing_the_rust_standard_l
    phase_adding_targets
    phase_applying_root_tweaks
    phase_installing_linker_packs
    phase_testing_the_installation
}
# --- tpf: end src/rustc-termux/install.sh ---
# --- tpf: begin src/rustc-termux/manage.sh ---
manage_init() {
    [ -d "$BASE" ] || die "No fake rustup install found in $BASE. Run: $TPF_SCRIPT install"
    HOST="$("$REAL_RUSTC" -vV 2>/dev/null | sed -n 's/^host: //p')"
    conf_load_quiet
}

# Output lines of the checks (problems are shown on stdout, in order).
bad() { _ui_line "$C_ERR" '[ERROR]' "$*"; }

# Day-to-day commands: status, doctor, test, targets, packs, linker, jobs, nightly, log.

set_setting() { # key value
    local k="$1" v="$2" cur
    touch "$BASE/settings"
    if grep -q "^$k=" "$BASE/settings"; then
        sed -i "s|^$k=.*|$k=$v|" "$BASE/settings"
    else printf '%s=%s\n' "$k" "$v" >>"$BASE/settings"; fi
    cur="$(setting "$k")"
    [ "$cur" = "$v" ]
}

setting() { sed -n "s/^$1=//p" "$BASE/settings" 2>/dev/null | head -n1; }

sysroot_dir() { "$REAL_RUSTC" --print sysroot; }

# A target's standard library is usable only with real .rlib files (Termux's
# package ships some Android targets with .rmeta metadata only).
std_ready() { compgen -G "$1/libcore-*.rlib" >/dev/null 2>&1; }

has_pack() { [ -e "$TOOLS/$1.installed" ]; }

installed_packs() {
    local p
    for p in $PACK_ALL; do has_pack "$p" && printf '%s ' "$p"; done
}

target_valid() { "$REAL_RUSTC" --print target-list 2>/dev/null | grep -qxF "$1"; }

target_register() { grep -qxF "$1" "$TARGETS_FILE" 2>/dev/null || echo "$1" >>"$TARGETS_FILE"; }

target_unregister() {
    [ -f "$TARGETS_FILE" ] || return 0
    grep -vxF "$1" "$TARGETS_FILE" >"$TARGETS_FILE.tmp"
    mv -f "$TARGETS_FILE.tmp" "$TARGETS_FILE"
}

# NDK naming (same rules as the installer)
ndk_triple() { case "$1" in armv7-linux-androideabi) echo armv7a-linux-androideabi24 ;; *) echo "${1}24" ;; esac }

write_clang_linker() { # target triple [sysroot]
    local t="$1" triple="$2" sysroot="${3:-}" out="$TOOLS/linkers/$1" lib
    mkdir -p "$TOOLS/linkers"
    # rustc links with -nodefaultlibs: the compiler-rt builtins (for example
    # __emutls_get_address on 32-bit Android) must be appended explicitly.
    lib="$(clang --target="$triple" --rtlib=compiler-rt --print-libgcc-file-name 2>/dev/null)"
    [ -f "$lib" ] || lib=""
    {
        echo '#!/data/data/com.termux/files/usr/bin/bash'
        printf 'exec clang --target=%s' "$triple"
        [ -z "$sysroot" ] || printf ' --sysroot=%s -B%s/lib -L%s/lib' "$sysroot" "$sysroot" "$sysroot"
        printf ' -fuse-ld=lld "$@"'
        [ -z "$lib" ] || printf ' "%s"' "$lib"
        echo
    } >"$out"
    chmod +x "$out"
}

linker_paths_ok() { # every absolute path written in a linker script must exist
    local f="$1" p missing=0
    for p in $(grep -oE '/data/data/[^ "]+' "$f" | sed 's/^-[A-Za-z]*//' | sort -u); do
        [ -e "$p" ] || {
            echo "$p"
            missing=1
        }
    done
    return $missing
}

cmd_status() {
    manage_init
    echo -e "${C_INFO}== Toolchain ==${C_RESET}"
    echo "rustc   : $("$REAL_RUSTC" --version 2>&1)"
    echo "cargo   : $("$REAL_CARGO" --version 2>&1)"
    echo "host    : $HOST"
    echo "rustup  : $(command -v rustup || echo 'not in PATH')"
    echo "nightly : $([ "$(setting nightly)" = 1 ] && echo 'simulated (on)' || echo off)"
    echo "jobs    : $(setting jobs | sed 's/^$/no limit/')"
    echo -e "${C_INFO}== Targets ==${C_RESET}"
    local sr t st
    sr="$(sysroot_dir)"
    if [ -s "$TARGETS_FILE" ]; then
        while IFS= read -r t; do
            [ -n "$t" ] || continue
            if std_ready "$sr/lib/rustlib/$t/lib"; then st="std ready"; else st="std built by cargo on first use"; fi
            printf '  %-34s %s%s\n' "$t" "$st" "$([ -x "$TOOLS/linkers/$t" ] && echo ', linker: yes')"
        done <"$TARGETS_FILE"
    else echo "  (none added)"; fi
    echo -e "${C_INFO}== Linker packs ==${C_RESET}"
    local p
    for p in $PACK_ALL; do printf '  %-6s %s\n' "$p" "$(has_pack "$p" && echo installed || echo '-')"; done
    echo -e "${C_INFO}== Root ==${C_RESET}"
    if [ "$(conf_get RT_USE_ROOT)" = 1 ]; then
        echo "tweaks  : $(conf_get RT_ROOT_TWEAKS)"
        echo "swap    : $(conf_get RT_SWAP_FILE)"
        echo "boot    : $(conf_get RT_BOOT_SCRIPT)"
    else echo "  root not used"; fi
    echo -e "${C_INFO}== Disk ==${C_RESET}"
    echo "free in \$HOME : $(df -Pk "$HOME" 2>/dev/null | awk 'NR==2 {printf "%d MB", $4/1024}')   Rust files: $(du -sh "$BASE" 2>/dev/null | cut -f1)"
}

cmd_linker() {
    manage_init
    local sub="${1:-list}"
    shift || true
    case "$sub" in
        list)
            local f t any=0 miss
            for f in "$TOOLS"/linkers/*; do
                [ -e "$f" ] || continue
                any=1
                t="$(basename "$f")"
                if [ ! -x "$f" ]; then
                    bad "$t: not executable"
                    continue
                fi
                if miss="$(linker_paths_ok "$f")"; then
                    ok "$t   ${C_DIM}$(tail -n1 "$f" | cut -c1-110)${C_RESET}"
                else bad "$t: missing: $(echo $miss | tr '\n' ' ')"; fi
            done
            [ "$any" = 1 ] || echo "No linker yet. Add one:  $TPF_SCRIPT linker add TARGET --ndk | --clang TRIPLE | --zig ZIGTARGET | -- CMD ARGS"
            ;;
        add)
            local t="${1:-}"
            shift || true
            [ -n "$t" ] || die "usage: linker add TARGET --ndk | --clang TRIPLE [--sysroot DIR] | --zig ZIGTARGET | -- CMD ARGS..."
            target_valid "$t" || die "unknown target: $t (see: rustup target list)"
            case "${1:-}" in
                --ndk)
                    local d="$PREFIX/$(ndk_dirname "$t")"
                    [ -d "$d" ] || die "No NDK sysroot at $d. Install it first:  pkg install ndk-multilib   (or: $TPF_SCRIPT packs add ndk)"
                    write_clang_linker "$t" "$(ndk_triple "$t")" "$d"
                    ;;
                --clang)
                    local triple="${2:-}" sysroot=""
                    [ -n "$triple" ] || die "--clang needs a triple (example: aarch64-linux-gnu)"
                    [ "${3:-}" = "--sysroot" ] && sysroot="${4:-}"
                    write_clang_linker "$t" "$triple" "$sysroot"
                    ;;
                --zig)
                    local zt="${2:-}" z
                    [ -n "$zt" ] || die "--zig needs a zig target (example: x86_64-linux-musl)"
                    z="$TOOLS/bin/zig"
                    [ -x "$z" ] || z="$(command -v zig || true)"
                    [ -n "$z" ] || die "zig not found (install the pack:  $TPF_SCRIPT packs add zig)"
                    mkdir -p "$TOOLS/linkers"
                    printf '#!/data/data/com.termux/files/usr/bin/bash\nexec "%s" cc -target %s "$@"\n' "$z" "$zt" >"$TOOLS/linkers/$t"
                    chmod +x "$TOOLS/linkers/$t"
                    ;;
                --)
                    shift
                    [ $# -gt 0 ] || die "give the command after --"
                    mkdir -p "$TOOLS/linkers"
                    {
                        echo '#!/data/data/com.termux/files/usr/bin/bash'
                        printf 'exec'
                        printf ' %q' "$@"
                        echo ' "$@"'
                    } >"$TOOLS/linkers/$t"
                    chmod +x "$TOOLS/linkers/$t"
                    ;;
                *) die "choose how to link: --ndk | --clang TRIPLE | --zig ZIGTARGET | -- CMD ARGS" ;;
            esac
            target_register "$t"
            ok "Linker for $t: $TOOLS/linkers/$t"
            info "The standard library for $t is built at the first build (or now:  rustup target add $t)."
            info "Check it:  $TPF_SCRIPT linker test $t"
            ;;
        remove)
            local t="${1:-}"
            [ -n "$t" ] || die "usage: linker remove TARGET"
            [ -e "$TOOLS/linkers/$t" ] || die "No linker for $t."
            rm -f "$TOOLS/linkers/$t"
            ok "Linker for $t removed (the target stays registered; remove it with: rustup target remove $t)."
            ;;
        test)
            local t="${1:-}" dir bin magic got
            [ -n "$t" ] || die "usage: linker test TARGET"
            dir="$(mktemp -d "$HOME/.rust-termux-test.XXXXXX")" || die "cannot create a test directory"
            info "Building a hello-world for $t (first time: the standard library is built, several minutes)..."
            if (cd "$dir" && env -u CARGO_TARGET_DIR cargo new --vcs none --quiet hello && cd hello && env -u CARGO_TARGET_DIR cargo build --quiet --target "$t"); then
                bin="$dir/hello/target/$t/debug/hello"
                magic=ELF
                case "$t" in *windows*)
                    bin="$bin.exe"
                    magic=MZ
                    ;;
                *wasm*)
                    bin="$dir/hello/target/$t/debug/hello.wasm"
                    magic=WASM
                    ;;
                esac
                case "$magic" in
                    ELF) got="$(head -c4 "$bin" 2>/dev/null | tail -c3)" ;;
                    MZ) got="$(head -c2 "$bin" 2>/dev/null)" ;;
                    WASM)
                        got="$(head -c4 "$bin" 2>/dev/null | tail -c3)"
                        [ "$got" = "asm" ] && got=WASM
                        ;;
                esac
                if [ "$got" = "$magic" ]; then
                    ok "$t: build works ($magic file)"
                    rm -rf "$dir"
                    return 0
                fi
                bad "$t: the build produced no valid $magic file"
            else bad "$t: the build failed (cargo output above)"; fi
            rm -rf "$dir"
            return 1
            ;;
        *) die "usage: linker list | add | remove | test" ;;
    esac
}

cmd_targets() {
    manage_init
    local sub="${1:-list}"
    shift || true
    case "$sub" in
        list) "$BASE/bin/rustup" target list --installed ;;
        add | remove)
            [ $# -gt 0 ] || die "usage: targets $sub TARGET..."
            "$BASE/bin/rustup" target "$sub" "$@"
            ;;
        *) die "usage: targets [list|add T...|remove T...]" ;;
    esac
}

pack_summary() {
    case "$1" in
        zig) echo "cross-link Linux (gnu/musl) and Windows-gnu with Zig + cargo-zigbuild" ;;
        msvc) echo "Windows MSVC targets with cargo-xwin (downloads the Windows SDK, Microsoft licence)" ;;
        ndk) echo "Android programs for the OTHER CPU families (armv7, i686, x86_64) with ndk-multilib" ;;
        wasm) echo "WebAssembly tools: binaryen (wasm-opt), wabt, wasm-bindgen-cli (compiled, 5-15 min)" ;;
    esac
}

cmd_packs() {
    manage_init
    local sub="${1:-list}"
    shift || true
    case "$sub" in
        list)
            local p
            for p in $PACK_ALL; do
                printf '  %-5s %-10s %s\n' "$p" "$(has_pack "$p" && echo installed || echo '-')" "$(pack_summary "$p")"
            done
            ;;
        add)
            [ $# -gt 0 ] || die "usage: packs add NAME... (among: $PACK_ALL)"
            packs_add "$@"
            ;;
        remove)
            [ $# -gt 0 ] || die "usage: packs remove NAME..."
            local p t c
            for p in "$@"; do
                pack_known "$p" || die "unknown pack: $p"
                has_pack "$p" || {
                    warn "$p is not installed."
                    continue
                }
                case "$p" in
                    zig)
                        for t in x86_64-unknown-linux-musl aarch64-unknown-linux-musl x86_64-unknown-linux-gnu aarch64-unknown-linux-gnu x86_64-pc-windows-gnu; do
                            target_unregister "$t"
                            rm -f "$TOOLS/linkers/$t"
                        done
                        env RUSTC="$REAL_RUSTC" "$REAL_CARGO" uninstall --root "$TOOLS" cargo-zigbuild >/dev/null 2>&1
                        rm -rf "$TOOLS/zig-dist" "$TOOLS/bin/zig" "$BASE/zig-cache" "$BASE/zigbuild-cache"
                        ;;
                    msvc)
                        for t in x86_64-pc-windows-msvc aarch64-pc-windows-msvc; do
                            target_unregister "$t"
                            rm -f "$TOOLS/linkers/$t"
                        done
                        env RUSTC="$REAL_RUSTC" "$REAL_CARGO" uninstall --root "$TOOLS" cargo-xwin >/dev/null 2>&1
                        rm -rf "$BASE/xwin-cache"
                        ;;
                    ndk) for t in armv7-linux-androideabi i686-linux-android x86_64-linux-android aarch64-linux-android; do
                        [ "$t" = "$HOST" ] && continue
                        target_unregister "$t"
                        rm -f "$TOOLS/linkers/$t"
                    done ;;
                    wasm) env RUSTC="$REAL_RUSTC" "$REAL_CARGO" uninstall --root "$TOOLS" wasm-bindgen-cli >/dev/null 2>&1 ;;
                esac
                rm -f "$TOOLS/$p.installed"
                ok "Pack removed: $p"
            done
            # keep the saved list in step with what is on disk
            if [ -f "$CONF" ]; then
                local now
                now="$(installed_packs)"
                now="${now% }"
                conf_set RT_PACKS "$now"
            fi
            info "Termux packages (ndk-multilib, binaryen, wabt, ...) were kept; remove them with pkg if you want."
            ;;
        *) die "usage: packs list | add NAME... | remove NAME..." ;;
    esac
}

cmd_jobs() {
    manage_init
    case "${1:-}" in
        off | 0 | "") set_setting jobs "" && ok "No limit on parallel build jobs." ;;
        *[!0-9]*) die "usage: jobs N|off" ;;
        *) set_setting jobs "$1" && ok "Parallel build jobs limited to $1 (too many can make Android kill Termux)." ;;
    esac
    [ -f "$CONF" ] && conf_set RT_JOBS "$(setting jobs)"
}

cmd_nightly() {
    manage_init
    case "${1:-}" in
        on) set_setting nightly 1 && ok "Simulated nightly mode enabled (cargo +nightly)." ;;
        off) set_setting nightly 0 && ok "Simulated nightly mode disabled." ;;
        *) die "usage: nightly on|off" ;;
    esac
    [ -f "$CONF" ] && conf_set RT_NIGHTLY "$(setting nightly)"
}

cmd_test() {
    manage_init
    local dir out
    dir="$(mktemp -d "$HOME/.rust-termux-test.XXXXXX")" || die "cannot create a test directory"
    if (cd "$dir" && env -u CARGO_TARGET_DIR cargo new --vcs none --quiet hello && cd hello && env -u CARGO_TARGET_DIR cargo run --quiet) >"$dir/out.log" 2>&1; then
        out="$(tail -n1 "$dir/out.log")"
        ok "Native build and run work: $out"
        rm -rf "$dir"
        return 0
    fi
    bad "Native build failed:"
    tail -n 12 "$dir/out.log"
    rm -rf "$dir"
    return 1
}

d_ok() {
    N_OK=$((N_OK + 1))
    ok "$*"
}

d_warn() {
    N_WARN=$((N_WARN + 1))
    warn "$*"
}

d_bad() {
    N_BAD=$((N_BAD + 1))
    bad "$*"
}

d_fixed() {
    N_FIXED=$((N_FIXED + 1))
    echo -e "      ${C_OK}-> fixed:${C_RESET} $*"
}

d_hint() { echo -e "      ${C_DIM}-> $*${C_RESET}"; }

cmd_doctor() {
    manage_init
    N_OK=0 N_WARN=0 N_BAD=0 N_FIXED=0
    local fix=0 full=0 a
    for a in "$@"; do case "$a" in --fix) fix=1 ;; --full) full=1 ;; *) die "usage: doctor [--fix] [--full]" ;; esac done
    local sr t f p ver

    echo -e "${C_INFO}== Compiler ==${C_RESET}"
    if ver="$("$REAL_RUSTC" --version 2>&1)"; then d_ok "rustc: $ver"; else
        d_bad "rustc does not run: $ver"
        d_hint "pkg reinstall rust"
    fi
    if "$REAL_CARGO" --version >/dev/null 2>&1; then d_ok "cargo runs"; else d_bad "cargo does not run"; fi
    for t in rustup cargo rustc; do
        if [ "$(command -v "$t")" = "$BASE/bin/$t" ]; then
            d_ok "'$t' resolves to the fake one"
        else
            d_warn "'$t' resolves to $(command -v "$t" || echo nothing)"
            d_hint "open a new Termux session or: source ~/.bashrc"
        fi
    done
    for t in clang lld make; do have "$t" && d_ok "$t present" || {
        d_bad "$t missing"
        d_hint "pkg install $t"
        if [ "$fix" = 1 ] && pkg install -y "$t" >/dev/null 2>&1; then d_fixed "installed $t"; fi
    }; done
    if [ ! -e "$BASE/bin/rust-lld" ] && have lld; then
        d_warn "rust-lld link missing (WebAssembly linking)"
        [ "$fix" = 1 ] && ln -sf "$(command -v lld)" "$BASE/bin/rust-lld" && d_fixed "rust-lld -> lld"
    fi

    echo -e "${C_INFO}== Rust sources ==${C_RESET}"
    sr="$(sysroot_dir)"
    if [ -d "$sr/lib/rustlib/src/rust/library" ] || [ -d "$sr/lib/rustlib/src" ]; then
        if [ "$(cat "$BASE/rust-src-version" 2>/dev/null)" = "$("$REAL_RUSTC" --version | awk '{print $2}')" ]; then
            d_ok "rust-src matches the compiler"
        else
            d_warn "rust-src was made for another compiler version"
            d_hint "$TPF_SCRIPT reinstall   (rebuilds everything cleanly)"
        fi
    else
        d_bad "Rust sources missing (needed to build the standard library of extra targets)"
        d_hint "$TPF_SCRIPT reinstall"
    fi

    echo -e "${C_INFO}== Targets ==${C_RESET}"
    if [ -s "$TARGETS_FILE" ]; then
        while IFS= read -r t; do
            [ -n "$t" ] || continue
            if std_ready "$sr/lib/rustlib/$t/lib"; then
                if [ -f "$BASE/std-installed/$t" ] && [ "$(cat "$BASE/std-installed/$t")" != "$("$REAL_RUSTC" --version)" ]; then
                    d_warn "$t: standard library built by another compiler version"
                    if [ "$fix" = 1 ] && "$BASE/bin/rustup" target add "$t" >/dev/null 2>&1; then d_fixed "rebuilt std for $t"; else d_hint "rustup target add $t"; fi
                else d_ok "$t: standard library ready"; fi
            elif [ -d "$sr/lib/rustlib/$t/lib" ]; then
                d_warn "$t: only .rmeta metadata files from the Termux package (no .rlib): the standard library is built at the first build (several minutes)"
                if [ "$fix" = 1 ]; then
                    rm -f "$BASE/std-installed/$t"
                    if "$BASE/bin/rustup" target add "$t" >/dev/null 2>&1; then d_fixed "std built for $t"; else d_hint "rustup target add $t  (see the output)"; fi
                else d_hint "build it now with: rustup target add $t   (or: doctor --fix). Not tested for this target yet."; fi
            else d_ok "$t: registered, standard library built at the first build"; fi
            if [ -e "$TOOLS/linkers/$t" ]; then :; else
                case "$t" in
                    "$HOST" | wasm32-* | *-none-* | *-none) ;; # bare metal and wasm: rustc uses lld alone
                    *-pc-windows-msvc) has_pack msvc || {
                        d_warn "$t: no linker (msvc pack not installed)"
                        d_hint "$TPF_SCRIPT packs add msvc"
                    } ;;
                    *-linux-gnu | *-linux-musl | *-windows-gnu) has_pack zig || {
                        d_warn "$t: no linker (zig pack not installed)"
                        d_hint "$TPF_SCRIPT packs add zig"
                    } ;;
                    *)
                        d_warn "$t: no linker registered (a link may use the wrong one)"
                        d_hint "$TPF_SCRIPT linker add $t ..."
                        ;;
                esac
            fi
        done <"$TARGETS_FILE"
    else d_ok "no extra target registered"; fi

    echo -e "${C_INFO}== Linkers ==${C_RESET}"
    for f in "$TOOLS"/linkers/*; do
        [ -e "$f" ] || continue
        t="$(basename "$f")"
        if [ ! -x "$f" ]; then
            d_bad "$t: linker not executable"
            [ "$fix" = 1 ] && chmod +x "$f" && d_fixed "chmod +x $t"
            continue
        fi
        if miss="$(linker_paths_ok "$f")"; then
            d_ok "$t: linker files exist"
        else
            d_bad "$t: linker refers to missing files: $(echo $miss | tr '\n' ' ')"
            case "$t" in
                armv7-linux-androideabi | i686-linux-android | x86_64-linux-android | aarch64-linux-android)
                    if [ "$fix" = 1 ] && [ -d "$PREFIX/$(ndk_dirname "$t")" ]; then
                        write_clang_linker "$t" "$(ndk_triple "$t")" "$PREFIX/$(ndk_dirname "$t")" && d_fixed "linker for $t regenerated"
                    else d_hint "pkg install ndk-multilib, then doctor --fix"; fi
                    ;;
                *) d_hint "$TPF_SCRIPT packs add <pack> or $TPF_SCRIPT linker add $t ..." ;;
            esac
        fi
    done

    echo -e "${C_INFO}== Packs ==${C_RESET}"
    for p in $PACK_ALL; do
        has_pack "$p" || continue
        case "$p" in
            zig) { [ -x "$TOOLS/bin/zig" ] || have zig; } && [ -x "$TOOLS/bin/cargo-zigbuild" ] && d_ok "zig: zig and cargo-zigbuild present" || {
                d_bad "zig: pack incomplete"
                d_hint "$TPF_SCRIPT packs remove zig && $TPF_SCRIPT packs add zig"
            } ;;
            msvc) [ -x "$TOOLS/bin/cargo-xwin" ] && [ -d "$BASE/xwin-cache" ] && d_ok "msvc: cargo-xwin and SDK cache present" || {
                d_bad "msvc: pack incomplete"
                d_hint "$TPF_SCRIPT packs remove msvc && $TPF_SCRIPT packs add msvc"
            } ;;
            ndk) have clang && dpkg -s ndk-multilib >/dev/null 2>&1 && d_ok "ndk: ndk-multilib installed" || {
                d_bad "ndk: ndk-multilib missing"
                d_hint "pkg install ndk-multilib"
            } ;;
            wasm) have wasm-opt && have wasm2wat && [ -x "$TOOLS/bin/wasm-bindgen" ] && d_ok "wasm: wasm-opt, wasm2wat, wasm-bindgen present" || {
                d_bad "wasm: pack incomplete"
                d_hint "$TPF_SCRIPT packs remove wasm && $TPF_SCRIPT packs add wasm"
            } ;;
        esac
    done
    [ -n "$(installed_packs)" ] || d_ok "no pack installed (optional)"

    echo -e "${C_INFO}== Bare metal and LTO ==${C_RESET}"
    local c any_std=0
    for f in "$BASE"/std-installed/*; do
        [ -f "$f" ] || continue
        any_std=1
        t="$(basename "$f")"
        c="$(ls "$sr/lib/rustlib/$t/lib"/libcore-*.rlib 2>/dev/null | head -n1)"
        [ -n "$c" ] || continue
        if grep -q llvmbc "$c" 2>/dev/null; then
            d_ok "$t: standard library carries LLVM bitcode (lto = true works)"
        else
            d_warn "$t: standard library built without LLVM bitcode: projects with 'lto = true' fail (Can't find section .llvmbc)"
            if [ "$fix" = 1 ]; then
                rm -rf "$sr/lib/rustlib/$t" "$f"
                if "$BASE/bin/rustup" target add "$t" >/dev/null 2>&1; then d_fixed "std rebuilt for $t with bitcode"; else d_hint "rustup target add $t (see the output)"; fi
            else d_hint "doctor --fix rebuilds it (a few minutes)"; fi
        fi
    done
    [ "$any_std" = 1 ] || d_ok "no standard library built by the fake rustup yet"
    if [ -x "$BASE/bin/arm-none-eabi-gcc" ] && [ -x "$BASE/bin/arm-none-eabi-ar" ]; then
        d_ok "arm-none-eabi-gcc / ar available (clang + llvm)"
    else
        d_warn "arm-none-eabi-* tools missing (build scripts of embedded projects expect them)"
        d_hint "$TPF_SCRIPT reinstall"
    fi

    echo -e "${C_INFO}== Root and system ==${C_RESET}"
    if [ "$(conf_get RT_USE_ROOT)" = 1 ]; then
        local sw
        sw="$(conf_get RT_SWAP_FILE)"
        if [ -n "$sw" ]; then
            if su -c "grep -q '${sw##*/}' /proc/swaps" 2>/dev/null; then
                d_ok "swap file active: $sw"
            else
                d_bad "swap file not active: $sw"
                if [ "$fix" = 1 ] && su -c "[ -f $sw ] && swapon $sw" >/dev/null 2>&1; then d_fixed "swapon $sw"; else d_hint "su -c 'swapon $sw'  (or doctor --fix)"; fi
            fi
        fi
        local bs
        bs="$(conf_get RT_BOOT_SCRIPT)"
        if [ -n "$bs" ]; then su -c "[ -f $bs ]" 2>/dev/null && d_ok "boot script present: $bs" || {
            d_bad "boot script missing: $bs"
            d_hint "$TPF_SCRIPT reinstall (root tweaks are asked again)"
        }; fi
        local w
        w="$(su -c 'cat /proc/sys/fs/inotify/max_user_watches' 2>/dev/null)"
        [ -n "$w" ] && { [ "$w" -ge 65536 ] && d_ok "inotify watches: $w" || d_warn "inotify watches only $w"; }
    else d_ok "root not used"; fi
    local free
    free="$(df -Pk "$HOME" 2>/dev/null | awk 'NR==2 {printf "%d", $4/1024}')"
    case "$free" in '' | *[!0-9]*) ;; *) [ "$free" -ge 1500 ] && d_ok "free space: ${free} MB" || d_warn "low free space: ${free} MB (standard libraries and linkers need room)" ;; esac
    [ -f "$CONF" ] && d_ok "settings file: $CONF" || d_warn "settings file missing: $CONF"

    if [ "$full" = 1 ]; then
        echo -e "${C_INFO}== Full test (compiles programs) ==${C_RESET}"
        cmd_test && d_ok "native build" || d_bad "native build"
        for t in $(cat "$TARGETS_FILE" 2>/dev/null); do
            if cmd_linker test "$t" >/dev/null 2>&1; then d_ok "$t builds"; else
                d_bad "$t does not build"
                d_hint "$TPF_SCRIPT linker test $t   (shows the error)"
            fi
        done
    else
        echo -e "${C_DIM}(add --full to also compile a program for every target; it can take minutes)${C_RESET}"
    fi

    echo
    echo -e "Result: ${C_OK}$N_OK ok${C_RESET}, ${C_WARN}$N_WARN warning(s)${C_RESET}, ${C_ERR}$N_BAD problem(s)${C_RESET}$([ "$fix" = 1 ] && echo ", $N_FIXED fixed")"
    [ "$N_BAD" -eq 0 ] || {
        [ "$fix" = 1 ] || echo "Try:  $TPF_SCRIPT doctor --fix"
        return 1
    }
    return 0
}

cmd_log() {
    local name="${1:-}" n="${2:-60}"
    [ -d "$LOG_DIR" ] || die "No install logs ($LOG_DIR)."
    if [ -z "$name" ]; then
        ls -1 "$LOG_DIR" | sed 's/\.log$//'
        echo "-> $TPF_SCRIPT log NAME [lines]"
        return 0
    fi
    [ -f "$LOG_DIR/$name.log" ] || [ -f "$LOG_DIR/$name" ] || die "No such log: $name"
    tail -n "$n" "$LOG_DIR/$name.log" 2>/dev/null || tail -n "$n" "$LOG_DIR/$name"
}
# --- tpf: end src/rustc-termux/manage.sh ---

TARGETS_ARG=""
NO_TARGETS=0
ROOT_MODE="" # "" = ask | yes | no
ROOT_TWEAKS_ARG=""
SWAP_ARG=""
PACKS_ARG=""
MSVC_LICENSE_ARG=0
NIGHTLY_ARG="" # "" = ask | 1 | 0
JOBS_ARG=""    # "" = ask | N
DO_RESET=0     # install keeps what works; reinstall cleans first
SKIP_UPDATE=0
NO_TEST=0
ADD_PACKS=0 # (kept for the install code: "packs add" works in place now)
LIST_PACKS=0

TOOL_RAW_COMMANDS="doctor targets packs linker"

TOOL_OPTIONS_HELP='      --targets LIST       install: targets to add, comma-separated (default: the saved ones)
      --no-targets         install: add no target now
      --nightly            install: enable the simulated nightly mode (cargo +nightly ...)
      --no-nightly         install: disable it
      --jobs N             install: limit parallel build jobs (0 = no limit; too many can make Android kill Termux)
      --root               install: use root (if available) for the SAFE tweaks, without asking
      --no-root            install: never use root, never ask for it
      --root-tweaks LIST   install: phantom,doze,inotify,oom,swap,perf (implies --root; swap and perf are never enabled by --yes alone)
      --swap-size MB       install: size of the swap file (default 2048)
      --toolchains LIST    install: linker packs among zig,msvc,ndk,wasm (or all, none)
      --accept-msvc-license  install: accept Microsoft'"'"'s licence for the msvc pack without asking
      --skip-update        install: skip `apt update` / `apt upgrade`
      --no-test            install: skip the compile tests at the end
      --purge-data         uninstall: also delete ~/.cargo and the saved settings'

tool_opt() {
    case "$1" in
        --targets)
            need_value "$1" $#
            TARGETS_ARG="$2"
            TOOL_SHIFT=2
            ;;
        --targets=*) TARGETS_ARG="${1#*=}" ;;
        --no-targets) NO_TARGETS=1 ;;
        --nightly) NIGHTLY_ARG=1 ;;
        --no-nightly) NIGHTLY_ARG=0 ;;
        --jobs)
            need_value "$1" $#
            JOBS_ARG="$2"
            TOOL_SHIFT=2
            ;;
        --jobs=*) JOBS_ARG="${1#*=}" ;;
        --purge-data) PURGE_DATA=1 ;;
        --root) ROOT_MODE="yes" ;;
        --no-root) ROOT_MODE="no" ;;
        --root-tweaks)
            need_value "$1" $#
            ROOT_TWEAKS_ARG="$2"
            ROOT_MODE="yes"
            TOOL_SHIFT=2
            ;;
        --root-tweaks=*)
            ROOT_TWEAKS_ARG="${1#*=}"
            ROOT_MODE="yes"
            ;;
        --swap-size)
            need_value "$1" $#
            SWAP_ARG="$2"
            TOOL_SHIFT=2
            ;;
        --swap-size=*) SWAP_ARG="${1#*=}" ;;
        --toolchains)
            need_value "$1" $#
            PACKS_ARG="$2"
            TOOL_SHIFT=2
            ;;
        --toolchains=*) PACKS_ARG="${1#*=}" ;;
        --accept-msvc-license) MSVC_LICENSE_ARG=1 ;;
        --skip-update) SKIP_UPDATE=1 ;;
        --no-test) NO_TEST=1 ;;
        *) return 1 ;;
    esac
}

# Checks the values given to the install options.
validate_options() {
    local t
    case "$TARGETS_ARG" in
        *[!A-Za-z0-9_.,-]*) die "--targets takes target names separated by commas (got: $TARGETS_ARG)" ;;
    esac
    [ -z "$JOBS_ARG" ] || is_uint "$JOBS_ARG" || die "--jobs must be a number (got: $JOBS_ARG)"
    [ -z "$SWAP_ARG" ] || { is_uint "$SWAP_ARG" && [ "$SWAP_ARG" -ge 256 ]; } || die "--swap-size must be a number of MB, at least 256 (got: $SWAP_ARG)"
    case "$ROOT_TWEAKS_ARG" in *[!a-z,]*) die "--root-tweaks takes names separated by commas (got: $ROOT_TWEAKS_ARG)" ;; esac
    ROOT_TWEAKS_ARG="${ROOT_TWEAKS_ARG//,/ }"
    for t in $ROOT_TWEAKS_ARG; do
        case " $ROOT_ALL " in *" $t "*) ;; *) die "Unknown root tweak: $t (known: ${ROOT_ALL// /,})" ;; esac
    done
    case "$PACKS_ARG" in *[!a-z,]*) die "--toolchains takes names separated by commas (got: $PACKS_ARG)" ;; esac
    case "$PACKS_ARG" in all) PACKS_ARG="${PACK_ALL// /,}" ;; none) PACKS_ARG="none" ;; esac
    for t in ${PACKS_ARG//,/ }; do
        [ "$t" = none ] || pack_known "$t" || die "Unknown toolchain pack: $t (known: ${PACK_ALL// /,})"
    done
}

# reinstall = remove the fake rustup and its leftovers, then install (the saved
# choices, ~/.cargo and the Termux packages are kept).
cmd_reinstall() {
    DO_RESET=1
    cmd_install "$@"
}

tool_usage() {
    printf 'Without --yes / --no, each install question defaults to the choice saved by the\nprevious run, or to a sensible value on a first install.\n'
}

add_command install "Install Rust, the fake rustup/cargo/rustc, targets and linker packs"
add_command reinstall "Remove the fake rustup, then install again from scratch"
add_command uninstall "Remove everything this tool wrote"
add_command status "What is installed and its state"
add_command doctor "Check everything (--fix repairs, --full also compiles programs)"
add_command test "Compile and run a native program"
add_command targets "list | add T | remove T"
add_command packs "list | add NAME... | remove NAME...   (zig msvc ndk wasm)"
add_command linker "list | add T --ndk|--clang TRIPLE|--zig ZT|-- CMD... | remove T | test T"
add_command jobs "N | off: limit parallel build jobs"
add_command nightly "on | off: simulated cargo +nightly"
add_command log "List the install logs, or show one: log NAME [lines]"

tpf_main "$@"
